/* ════════════════════════════════════════════════════════════════
   📊 ChartLabels — طبقة موحدة لعرض النصوص الكاملة في كل الرسوم
   ----------------------------------------------------------------
   الهدف (طلب أولاً في المواصفات): منع قص أسماء المدارس/الفئات/المحافظات
   على المحاور، وعرضها كاملة داخل Tooltip، وتطبيق Wrap/Rotation تلقائياً
   على المحاور الطويلة — عبر إعداد عام واحد يُطبَّق على جميع الرسوم
   الحالية والمستقبلية بدون لمس كل رسم على حدة.

   الفكرة: لا نقص مصفوفة labels في الذاكرة أبداً (تبقى كاملة، فيقرأها
   الـ Tooltip كاملة). القص/اللف يحدث فقط لحظة الرسم على المحور عبر
   tick callback عام.
   ════════════════════════════════════════════════════════════════ */
(function () {
  if (typeof Chart === "undefined") return;

  // أقصى طول للسطر الواحد قبل اللف، وأقصى عدد أسطر قبل وضع …
  const MAX_LINE = 16;
  const MAX_LINES = 3;

  // يحوّل نصاً طويلاً إلى مصفوفة أسطر (Chart.js يعرض المصفوفة كـ multi-line)
  function wrapLabel(raw) {
    const s = String(raw ?? "").trim();
    if (!s) return "—";
    if (s.length <= MAX_LINE) return s;
    const words = s.split(/\s+/);
    const lines = [];
    let cur = "";
    for (const w of words) {
      if (!cur) {
        cur = w;
      } else if ((cur + " " + w).length <= MAX_LINE) {
        cur += " " + w;
      } else {
        lines.push(cur);
        cur = w;
      }
      if (lines.length >= MAX_LINES) break;
    }
    if (cur && lines.length < MAX_LINES) lines.push(cur);
    // لو فاض النص عن الحد الأقصى للأسطر، نضع … في آخر سطر
    if (lines.length >= MAX_LINES) {
      const joinedLen = lines.join(" ").length;
      if (joinedLen < s.length) lines[MAX_LINES - 1] = lines[MAX_LINES - 1] + "…";
    }
    return lines;
  }

  // النص الكامل لتسمية معيّنة (يُستخدم في Tooltip) — يقرأ من data.labels الكاملة
  window.ChartLabels = {
    wrapLabel: wrapLabel,
    full(chart, index) {
      const lbls = chart?.data?.labels;
      if (Array.isArray(lbls) && index != null && lbls[index] != null) {
        const v = lbls[index];
        return Array.isArray(v) ? v.join(" ") : String(v);
      }
      return null;
    },
  };

  // tick callback عام: يلفّ التسمية الطويلة بدل قصها بـ …
  // يُطبَّق على المحور الفئوي (category) فقط حتى لا يلمس المحاور الرقمية.
  function wrappingTickCallback(value, index) {
    // على المحور الفئوي، value = الفهرس؛ نقرأ التسمية الأصلية الكاملة
    const lbl = this.getLabelForValue ? this.getLabelForValue(value) : value;
    return wrapLabel(lbl);
  }

  Chart.register({
    id: "ix_full_labels",
    // قبل أول رسم: نفعّل اللف على المحور الفئوي + نضمن tooltip بالنص الكامل
    afterInit(chart) {
      try {
        const scales = chart.config.options?.scales || {};
        for (const axisId of Object.keys(scales)) {
          const ax = scales[axisId];
          if (!ax) continue;
          const isCategory =
            ax.type === "category" ||
            (ax.type == null && (axisId === "x" || axisId === "y"));
          if (!isCategory) continue;
          ax.ticks = ax.ticks || {};
          // لا نلمس callback مخصّص موجود مسبقاً (احترام إعدادات الرسم)
          if (typeof ax.ticks.callback !== "function") {
            ax.ticks.callback = wrappingTickCallback;
          }
          if (ax.ticks.autoSkip == null) ax.ticks.autoSkip = true;
          if (ax.ticks.maxRotation == null) ax.ticks.maxRotation = 0;
        }
      } catch (_) {}
    },
  });

  // Tooltip عام: لو لم يحدّد الرسم title خاصاً به، نعرض النص الكامل للتسمية
  const _origTitle =
    (Chart.defaults.plugins.tooltip.callbacks &&
      Chart.defaults.plugins.tooltip.callbacks.title) ||
    null;
  Chart.defaults.plugins.tooltip.callbacks =
    Chart.defaults.plugins.tooltip.callbacks || {};
  Chart.defaults.plugins.tooltip.callbacks.title = function (items) {
    if (!items || !items.length) return "";
    const it = items[0];
    const full = window.ChartLabels.full(it.chart, it.dataIndex);
    if (full && full !== "—") return full;
    if (typeof _origTitle === "function") return _origTitle.call(this, items);
    return it.label || "";
  };
})();


/* تحديد لغة الصفحة (عربي افتراضياً) */
window.LANG = window.LANG || "ar";


/* وضع العرض المؤقت: إخفاء/إظهار عناصر محددة بدون حذف أي كود */
// عند الفتح دايماً تبويبات "الطلاب وعمر المبنى" و"استهلاك الوقود" مخفية (ON)
// — المستخدم هو اللي يقرر يظهرها يدوياً (من زر العين جوا أو برّه)
window.__PRESENTATION_MODE__ = true;

// أسماء التبويبات (name في PORTAL_CATEGORIES) المخفية في وضع العرض —
// أضف أي اسم تبويب هنا عشان يختفي تلقائياً من: كارت الصفحة الرئيسية (برا)،
// القائمة الجانبية داخل القسم (جوا)، ونافذة الاختصارات — بدون حذف أي كود.
var PRESENTATION_HIDDEN_TABS = ["students"];
function __isPresentationHiddenTab(name) {
  return !!window.__PRESENTATION_MODE__ && PRESENTATION_HIDDEN_TABS.indexOf(name) !== -1;
}

function setPresentationMode(nextMode) {
  window.__PRESENTATION_MODE__ = !!nextMode;
  applyPresentationModeUI();
}

function togglePresentationMode() {
  setPresentationMode(!window.__PRESENTATION_MODE__);
}

function applyPresentationModeUI() {
  const on = !!window.__PRESENTATION_MODE__;
  const idsToHide = [
    "tabbtn-students",
    "tab-students",
    "kpi-students-total",
    "kpi-students-max",
    "kpi-age-avg",
    "kpi-age-old",
    "kpi-age-new",
  ];
  idsToHide.forEach((id) => {
    const el = document.getElementById(id);
    if (el) el.classList.toggle("presentation-hidden", on);
  });

  // الرقم الحقيقي دايماً — لا يُستبدل بأي رقم وهمي
  const kTotal = document.getElementById("k-total");
  if (kTotal && window.__ACTUAL_K_TOTAL__ != null) {
    kTotal.textContent = window.__ACTUAL_K_TOTAL__;
  }

  const btn = document.getElementById("btnPresentationMode");
  if (btn) {
    btn.classList.toggle("on", on);
    btn.setAttribute("aria-pressed", on ? "true" : "false");
    btn.title = on ? "إخفاء التبويبات: ON" : "إخفاء التبويبات: OFF";
    btn.textContent = on ? "👁" : "◌";
  }

  // زر العين الخارجي (في صفحة البوابة portal-home) — أيقونة صغيرة زي الجوانية بالظبط
  const btnOuter = document.getElementById("btnPresentationModeOuter");
  if (btnOuter) {
    btnOuter.classList.toggle("on", on);
    btnOuter.setAttribute("aria-pressed", on ? "true" : "false");
    btnOuter.title = on
      ? "تبويب الطلاب وعمر المبنى مخفي — اضغط للإظهار"
      : "تبويب الطلاب وعمر المبنى ظاهر — اضغط للإخفاء";
    btnOuter.textContent = on ? "👁" : "◌";
    btnOuter.style.opacity = on ? ".35" : ".12";
  }

  if (on) {
    const activeTab = document.querySelector(".tab.active");
    if (activeTab && activeTab.id === "tabbtn-students") {
      const fallback = document.querySelector('.tab[onclick*="showTab(\'overview\'"]');
      if (fallback && typeof showTab === "function") showTab("overview", fallback);
    }
  }

  // حدّث ليستة التبويبات الظاهرة تحت كل كارت في صفحة البوابة (Portal Home)
  if (typeof __fillPortalCardTabsList === "function") __fillPortalCardTabsList();
}

document.addEventListener("DOMContentLoaded", () => {
  // عند كل فتح: تأكد إن الوضع ON (كروت الطلاب/عمر المبنى مخفية افتراضياً)
  window.__PRESENTATION_MODE__ = true;
  applyPresentationModeUI();
  document.addEventListener("keydown", (e) => {
    if (e.ctrlKey && e.shiftKey && (e.key || "").toLowerCase() === "p") {
      e.preventDefault();
      togglePresentationMode();
    }
  });
});


