let RAW = [],
  FILTERED = [],
  CHARTS = {},
  autoTimer = null,
  retryCount = 0,
  _filterTimer = null;
// جسر لـ window.CHARTS: CHARTS كائن ثابت المرجع (يتغيّر بالتعديل على
// خصائصه فقط عبر CHARTS[id]=...، وما بيتغيّرش الكائن نفسه أبداً) — فربطه
// مرة واحدة هنا كافٍ ويفضل متزامن تلقائياً. مطلوب لطبقة "mx-fca" (أسفل
// الملف) اللي بتقرأ window.CHARTS لرسم/حذف الرسوم البديلة.
window.CHARTS = CHARTS;
const TBL = { cur: 0, PAGE: 50 };
function getVal(row, field) {
  for (const k of COLS[field] || [field]) {
    const v = row[k];
    if (null != v && "" !== v && "#N/A" !== v && "NaT" !== v) return v;
  }
  return null;
}

/* ════════════════════════════════════════════════════════════════
   🗄️ DataService — طبقة البيانات الموحّدة (Unified Data Layer)
   ----------------------------------------------------------------
   نقطة الوصول الرسمية الوحيدة لبيانات اللوحة. تغلّف المصدر الموحّد
   (RAW المُطبَّع + FILTERED بعد الفلاتر) وتوفّر دوال قراءة/تنظيف/
   تجميع/عدّ موحّدة مع Caching بسيط. أي جزء جديد في المشروع يجب أن
   يقرأ من هنا فقط (Single Source of Truth) بدل تكرار حلقات الفلترة
   والتجميع. الدوال القائمة تبقى تعمل كما هي؛ هذه الطبقة تغلّفها.
   ════════════════════════════════════════════════════════════════ */
const DataService = (function () {
  const _cache = new Map();
  const _key = (...a) => a.map((x) => JSON.stringify(x)).join("|");

  // تنظيف قيمة نصية موحّد (null/undefined/NaN/#N/A/فراغات)
  function cleanText(v, fallback = "") {
    if (v == null) return fallback;
    const s = String(v).replace(/\uFEFF/g, "").trim();
    if (!s || s === "—" || s === "#N/A" || s === "NaT" || s === "null" || s === "undefined")
      return fallback;
    return s.replace(/\s+/g, " ");
  }
  // تحويل لرقم موحّد (يعيد null لو غير صالح)
  function toNum(v) {
    if (v == null || v === "" || v === "#N/A" || v === "NaT") return null;
    const n = parseFloat(String(v).replace(/,/g, ""));
    return isFinite(n) ? n : null;
  }

  return {
    cleanText,
    toNum,
    invalidateCache() {
      _cache.clear();
    },
    /** كل السجلّات الخام المُطبَّعة (للقراءة فقط منطقياً) */
    all() {
      return typeof RAW !== "undefined" && Array.isArray(RAW) ? RAW : [];
    },
    /** السجلّات بعد تطبيق الفلاتر الحالية — المصدر الافتراضي لكل عرض */
    filtered() {
      return typeof FILTERED !== "undefined" && Array.isArray(FILTERED) ? FILTERED : this.all();
    },
    /** قيمة حقل مُعرّف في COLS لسجل واحد (تعتمد أسماء الهيدرز فقط) */
    field(row, fieldKey) {
      return typeof getVal === "function" ? getVal(row, fieldKey) : row?.[fieldKey] ?? null;
    },
    /** عدّ حسب فئة، مرتّب تنازلياً (مع Cache) */
    countBy(arr, key, n = Infinity) {
      const k = _key("countBy", arr === this.filtered() ? "F" : "A", key, n);
      if (_cache.has(k)) return _cache.get(k);
      const map = {};
      (arr || []).forEach((r) => {
        const v = cleanText(r[key]);
        if (!v) return;
        map[v] = (map[v] || 0) + 1;
      });
      const out = Object.entries(map)
        .sort((a, b) => b[1] - a[1])
        .slice(0, n)
        .map(([name, count]) => ({ name, count }));
      _cache.set(k, out);
      return out;
    },
    /** متوسط حقل رقمي */
    avg(arr, key) {
      const vals = (arr || []).map((r) => toNum(r[key])).filter((v) => v != null);
      return vals.length ? +(vals.reduce((a, b) => a + b, 0) / vals.length).toFixed(2) : null;
    },
    /** مجموع حقل رقمي */
    sum(arr, key) {
      return (arr || []).reduce((s, r) => s + (toNum(r[key]) || 0), 0);
    },
    /** أعلى/أدنى n حسب حقل رقمي */
    topN(arr, key, n = 10, asc = false) {
      const valid = (arr || []).filter((r) => toNum(r[key]) != null);
      return [...valid]
        .sort((a, b) => (asc ? toNum(a[key]) - toNum(b[key]) : toNum(b[key]) - toNum(a[key])))
        .slice(0, n);
    },
    /** تجميع مجموع قيمة رقمية حسب فئة */
    groupBySum(arr, groupKey, numKey, n = Infinity) {
      const map = {};
      (arr || []).forEach((r) => {
        const g = cleanText(r[groupKey]);
        const v = toNum(r[numKey]);
        if (!g || v == null) return;
        map[g] = (map[g] || 0) + v;
      });
      return Object.entries(map)
        .sort((a, b) => b[1] - a[1])
        .slice(0, n)
        .map(([name, value]) => ({ name, value: +value.toFixed(2) }));
    },
  };
})();
window.DataService = DataService;
const num = (v) => {
    if (null == v || "" === v || "#N/A" === v || "NaT" === v) return null;
    const n = parseFloat(String(v).replace(/,/g, ""));
    return isFinite(n) ? n : null;
  },
  fmt = (v, d = 0) =>
    null == v
      ? "—"
      : Number(v).toLocaleString("en-US", { minimumFractionDigits: d, maximumFractionDigits: d }),
  pct = (v, d = 1) => (null == v ? "—" : fmt(v, d) + "%"),
  esc = (s) =>
    String(s ?? "").replace(
      /[&<>"']/g,
      (m) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[m],
    ),
  avg = (arr) => (arr.length ? arr.reduce((a, b) => a + b, 0) / arr.length : null);
function getTier(v) {
  return null == v
    ? null
    : v <= 24.99
      ? "critical"
      : v <= 49.99
        ? "fair"
        : v <= 74.99
          ? "good"
          : "vgood";
}
const tierColor = (v) => TIER[getTier(v)]?.color || CSS_TOKENS.txMuted(),
  tierBg = (v) => TIER[getTier(v)]?.bg || "#f1f5f9";
function killChart(id) {
  if (CHARTS[id]) {
    try {
      CHARTS[id].destroy();
    } catch (_) {}
    delete CHARTS[id];
    delete CHART_SIGS[id];
  }
}

/* Task 2: منع إعادة إنشاء الرسم إذا لم تتغير بياناته فعلياً.
   نخزّن بصمة JSON لبيانات كل رسم؛ لو البصمة مطابقة والرسم موجود نتخطى إعادة الرسم. */
const CHART_SIGS = {};
function chartUnchanged(id, sigParts) {
  let sig;
  try { sig = JSON.stringify(sigParts); } catch (_) { return false; }
  if (CHARTS[id] && CHART_SIGS[id] === sig) return true;
  CHART_SIGS[id] = sig;
  return false;
}

/* ════════════════════════════════════════════════════════════════
   🛡️ دوال حماية عامة للرسوم البيانية (Chart.js Sanitizers)
   هدفها: منع ظهور undefined / null / NaN على أي محور أو تسمية أو
   tooltip في أي رسم بياني بالداشبورد بالكامل — تُستخدم كطبقة حماية
   أخيرة قبل تمرير البيانات لـ new Chart(...)
   ════════════════════════════════════════════════════════════════ */

// ينظّف قيمة نصية مفردة (label واحد): يرجع fallback لو القيمة فاضية/تالفة
function sanitizeText(value, fallback = "غير متوفر") {
  if (value === null || value === undefined) return fallback;
  if (typeof value === "number" && !Number.isFinite(value)) return fallback;
  const s = String(value).trim();
  if (!s || s === "undefined" || s === "null" || s === "NaN" || s === "#N/A") return fallback;
  return s;
}

// ينظّف قيمة رقمية مفردة: يرجع fallback (افتراضيًا null، آمن لـ Chart.js) لو القيمة غير صالحة
function safeNumber(value, fallback = null) {
  if (value === null || value === undefined || value === "") return fallback;
  const n = typeof value === "number" ? value : Number(String(value).replace(/,/g, "").trim());
  return Number.isFinite(n) ? n : fallback;
}

// يضمن أن القيمة دائماً مصفوفة (يحوّل أي قيمة غير مصفوفة لمصفوفة فاضية)
function safeArray(value) {
  return Array.isArray(value) ? value : [];
}

// ينظّف مصفوفة تسميات (labels) كاملة لرسم بياني — كل عنصر يصبح نصاً آمناً دائماً
function sanitizeChartLabels(labels, fallback = "غير متوفر") {
  return safeArray(labels).map((l) => sanitizeText(l, fallback));
}

// ينظّف مصفوفة بيانات رقمية (data) كاملة — كل عنصر يصبح رقماً صالحاً أو null
function sanitizeChartValues(values) {
  return safeArray(values).map((v) => safeNumber(v, null));
}

/* ينظّف labels + datasets معاً قبل تمريرهما لـ Chart.js:
   - يوحّد طول labels مع أطول dataset
   - ينظّف كل تسمية وكل قيمة رقمية
   - dataset بدون أي قيمة صالحة يُستثنى تلقائياً من الرسم */
function normalizeChartData(labels, datasets) {
  const safeDatasets = safeArray(datasets)
    .map((ds) => {
      if (!ds || typeof ds !== "object") return null;
      const cleanData = sanitizeChartValues(ds.data);
      const hasAnyValidValue = cleanData.some((v) => v !== null);
      if (!cleanData.length || !hasAnyValidValue) return null; // dataset بدون أي قيمة صالحة لا يُرسم
      return { ...ds, label: sanitizeText(ds.label, ""), data: cleanData };
    })
    .filter(Boolean);
  const maxLen = safeDatasets.reduce((m, ds) => Math.max(m, ds.data.length), 0);
  let cleanLabels = sanitizeChartLabels(labels);
  // لو الـ labels أقصر من البيانات، نكمّلها بقيمة آمنة بدل ما تظهر undefined
  while (cleanLabels.length < maxLen) cleanLabels.push("غير متوفر");
  return { labels: cleanLabels, datasets: safeDatasets };
}

// يعرض رسالة "لا توجد بيانات" أنيقة بدل الكانفس الفاضي عند عدم وجود بيانات كافية لرسم شارت
function renderEmptyState(container, message = "لا توجد بيانات متاحة") {
  const el = typeof container === "string" ? document.getElementById(container) : container;
  if (!el) return;
  el.innerHTML = `<div class="chart-empty-state" style="display:flex;flex-direction:column;align-items:center;justify-content:center;height:100%;min-height:160px;color:var(--tx-muted);gap:8px">
    <div style="font-size:30px;opacity:.5">📭</div>
    <div style="font-size:12px;font-weight:700">${sanitizeText(message)}</div>
  </div>`;
}

/* ── حالات UX موحّدة (تحميل / خطأ / Skeleton) — طلب السادس عشر ── */
function renderLoadingState(container, message = "جاري التحميل…") {
  const el = typeof container === "string" ? document.getElementById(container) : container;
  if (!el) return;
  el.innerHTML = `<div class="chart-loading-state" style="display:flex;flex-direction:column;align-items:center;justify-content:center;height:100%;min-height:160px;color:var(--tx-muted);gap:10px">
    <div class="ix-skeleton-spinner" style="width:26px;height:26px;border:3px solid ${CSS_TOKENS.α(CSS_TOKENS.info(),.15)};border-top-color:#0891B2;border-radius:50%;animation:ixspin .8s linear infinite"></div>
    <div style="font-size:12px;font-weight:700">${sanitizeText(message)}</div>
  </div>`;
}
function renderErrorState(container, message = "تعذّر عرض البيانات") {
  const el = typeof container === "string" ? document.getElementById(container) : container;
  if (!el) return;
  el.innerHTML = `<div class="chart-error-state" style="display:flex;flex-direction:column;align-items:center;justify-content:center;height:100%;min-height:160px;color:#DC2626;gap:8px">
    <div style="font-size:28px;opacity:.6">⚠️</div>
    <div style="font-size:12px;font-weight:700">${sanitizeText(message)}</div>
  </div>`;
}
function renderSkeleton(container, lines = 4) {
  const el = typeof container === "string" ? document.getElementById(container) : container;
  if (!el) return;
  let html = '<div class="ix-skeleton" style="display:flex;flex-direction:column;gap:10px;padding:12px">';
  for (let i = 0; i < lines; i++) {
    html += `<div style="height:14px;border-radius:6px;background:linear-gradient(90deg,rgba(168,195,214,.18) 25%,rgba(168,195,214,.34) 37%,rgba(168,195,214,.18) 63%);background-size:400% 100%;animation:ixshimmer 1.4s ease infinite;width:${90 - i * 8}%"></div>`;
  }
  html += "</div>";
  el.innerHTML = html;
}

window.IXStates = { renderEmptyState, renderLoadingState, renderErrorState, renderSkeleton };

/* Callback آمن لمحاور Chart.js (ticks.callback) — يُستخدم في scales.x/y.ticks.callback
   لمنع ظهور undefined/null/NaN حتى لو وصلت القيمة الخام فاسدة لأي سبب وقت الرسم فعلياً.
   يعمل مع كلا نوعي المحاور: category (تمرّر index، نجيب label الحقيقي) وlinear (تمرّر القيمة مباشرة). */
function safeTickCallback(value, index, ticks) {
  const hasLabelGetter = this && typeof this.getLabelForValue === "function";
  const raw = hasLabelGetter ? this.getLabelForValue(value) : value;
  // لو الناتج رقم صالح (محور خطي)، نرجّعه كرقم بدل تحويله لنص "غير متوفر"
  if (typeof raw === "number" && Number.isFinite(raw)) return raw;
  const clean = sanitizeText(raw, "");
  // لف التسميات النصية الطويلة بدل قصها (يعتمد على الطبقة العامة ChartLabels)
  if (window.ChartLabels && typeof clean === "string") return window.ChartLabels.wrapLabel(clean);
  return clean;
}

