                data: stageArr.map((s) => s[1].qty),
                backgroundColor: stageArr.map(
                  (_, i) => [CSS_TOKENS.positive(), COLOR, CSS_TOKENS.special(), CSS_TOKENS.warning()][i % 4] + "BB",
                ),
