          إجمالي_الكمية_المطلوبة_احتياج: +إجمالي_احتياج_كمية.toFixed(2),
          إجمالي_قيمة_الاحتياج_ريال: +إجمالي_احتياج_قيمة.toFixed(2),
          إجمالي_الكمية_PPP: +إجمالي_PPP_كمية.toFixed(2),
