/* تاب 7: الأنظمة الرئيسية (مع قائمة رئيسي → فرعي + فلترة) */
function _hPanelMainSystems(body) {
  const ctx = HASR._ctx;
  /* إذا كان هناك context مدرسة واحدة: نعرض أنظمة تلك المدرسة فقط */
  const sc = HASR._schoolCtx;
  let sys;
  if (sc) {
    sys = [...(sc.systems||[])].filter(s=>s.total>0).sort((a,b)=>(b.total||0)-(a.total||0));
  } else {
    sys = ctx.systems;
  }
  const totAll = sys.reduce((t,x)=>t+(x.total||0),0) || 1;

  const ctxBanner = sc
    ? `<div style="display:flex;align-items:center;gap:8px;margin-bottom:10px;padding:8px 10px;background:rgba(30,58,138,.08);border-radius:8px;border:1px solid rgba(30,58,138,.18);flex-wrap:wrap">
        <span style="font-size:14px;color:#1E3A8A;font-weight:700">🏫 ${_hE(sc.name)}</span>
        <span style="font-size:13px;color:var(--tx-muted)">${_hE(sc.city)} · ${_hE(sc.code)}</span>
        <button onclick="HASR._schoolCtx=null;hasrTab('systems')" style="margin-right:auto;font-size:12.5px;padding:2px 8px;border-radius:999px;background:#E0E7FF;color:#3730A3;border:none;cursor:pointer;font-family:Tajawal">✕ عرض جميع المدارس</button>
      </div>`
    : '';

  body.innerHTML = `
    ${ctxBanner}
    <div class="hasr-igrid">
      <div class="hasr-ic full" style="--hc:#1E3A8A">
        <div class="hasr-ic-lbl">عدد الأنظمة الرئيسية</div>
        <div class="hasr-ic-val">${sys.length.toLocaleString('ar')}</div>
      </div>
    </div>
    <div class="hasr-sec">الأنظمة الرئيسية — اضغط لعرض الفرعية وتطبيق الفلتر</div>
    ${!sys.length
      ? '<div style="text-align:center;padding:20px;color:var(--tx-muted);font-size:14.5px">لا توجد أنظمة</div>'
      : sys.map(s=>{
          const tot=s.total||1;
          const isActive = ctx.filter.mainSys===s.name && !ctx.filter.subSys;
          return `
          <div class="hasr-srow" onclick="hasrSelectMainSystem('${_hE(s.name)}')"
               style="border:1.5px solid ${isActive?CSS_TOKENS.α(CSS_TOKENS.info(),.4):'transparent'};background:${isActive?CSS_TOKENS.α(CSS_TOKENS.info(),.06):''}">
            <div style="flex:1">
              <div class="hasr-sname">${_hE(s.name)}</div>
              <div style="display:flex;border-radius:5px;overflow:hidden;height:7px;background:var(--bd-light);margin-top:5px">
                ${s.excellent>0?`<div style="flex:${s.excellent};background:#10B981"></div>`:''}
                ${s.good>0?`<div style="flex:${s.good};background:#3B82F6"></div>`:''}
                ${s.bad>0?`<div style="flex:${s.bad};background:#F59E0B"></div>`:''}
                ${s.deteriorated>0?`<div style="flex:${s.deteriorated};background:#EF4444"></div>`:''}
              </div>
              <div class="hasr-smeta" style="margin-top:4px">${((tot/totAll)*100).toFixed(1)}% من الإجمالي</div>
            </div>
            <div class="hasr-sbadge">${(s.total||0).toLocaleString('ar')} أصل</div>
          </div>`;
        }).join('')}
  `;
}

/* تاب 8: الأنظمة الفرعية (كارت جديد) */
function _hPanelSubSystems(body) {
  const ctx  = HASR._ctx;
  const subs = ctx.allSubSystems;
  const totAll = subs.reduce((t,x)=>t+(x.total||0),0) || 1;
  body.innerHTML = `
    <div class="hasr-igrid">
      <div class="hasr-ic full" style="--hc:#0E7490">
        <div class="hasr-ic-lbl">إجمالي الأنظمة الفرعية</div>
        <div class="hasr-ic-val">${subs.length.toLocaleString('ar')}</div>
      </div>
    </div>
    <div class="hasr-sec">الأنظمة الفرعية — اضغط لتطبيق الفلتر</div>
    ${!subs.length
      ? '<div style="text-align:center;padding:20px;color:var(--tx-muted);font-size:14.5px">لا توجد أنظمة فرعية</div>'
      : subs.map(sub=>{
          const isActive = ctx.filter.subSys===sub.name && ctx.filter.mainSys===sub.mainSys;
          return `
          <div class="hasr-srow" onclick="hasrSelectSubSystem('${_hE(sub.mainSys)}','${_hE(sub.name)}')"
               style="border:1.5px solid ${isActive?'rgba(14,116,144,.4)':'transparent'};background:${isActive?'rgba(14,116,144,.06)':''}">
            <div style="flex:1">
              <div class="hasr-sname">${_hE(sub.name)}</div>
              <div class="hasr-smeta">${_hE(sub.mainSys)}</div>
              <div style="display:flex;border-radius:5px;overflow:hidden;height:6px;background:var(--bd-light);margin-top:4px">
                ${sub.excellent>0?`<div style="flex:${sub.excellent};background:#10B981"></div>`:''}
                ${sub.good>0?`<div style="flex:${sub.good};background:#3B82F6"></div>`:''}
                ${sub.bad>0?`<div style="flex:${sub.bad};background:#F59E0B"></div>`:''}
                ${sub.deteriorated>0?`<div style="flex:${sub.deteriorated};background:#EF4444"></div>`:''}
              </div>
            </div>
            <div class="hasr-sbadge">${(sub.total||0).toLocaleString('ar')} أصل</div>
          </div>`;
        }).join('')}
  `;
}

/* ════════════════════════════════════════════════════════════════
   اختيار نظام رئيسي من البانيل → عرض الفرعية في نفس البانل
════════════════════════════════════════════════════════════════ */
function hasrSelectMainSystem(mainSys) {
  const ctx = HASR._ctx;
  const sc  = HASR._schoolCtx;

  /* نأخذ الأنظمة الفرعية: من المدرسة لو في سياق، وإلا من الإجمالي */
  let sysEntry;
  if (sc) {
    const rawSchool = (HASR.data?.schools||[]).find(s=>s.code===sc.code);
    sysEntry = (rawSchool?.systems||[]).find(s=>s.name===mainSys);
  } else {
    sysEntry = ctx.systems.find(s=>s.name===mainSys) ||
               (HASR.data?.systems||[]).find(s=>s.name===mainSys);
  }
  const subs    = sysEntry ? (sysEntry.subSystems||[]) : [];
  const totAll  = subs.reduce((t,s)=>t+(s.total||0),0) || 1;

  /* نفتح البانل الفرعي الجانبي (يمين) — البانل الرئيسي يفضل زي ما هو */
  hasrOpenSubPanel();
  const body = document.getElementById('hasr-spr-body');
  if (!body) return;

  /* رأس البانل الفرعي */
  _hS('hasr-spr-title', '⚙️ ' + mainSys);
  const spSub = document.getElementById('hasr-spr-sub');
  if (spSub) spSub.textContent = sc
    ? ('🏫 ' + sc.name + ' · ' + subs.length + ' نظام فرعي')
    : (subs.length + ' نظام فرعي');

  /* بنر المدرسة لو في سياق */
  const schoolBanner = sc
    ? `<div style="display:flex;align-items:center;gap:8px;margin-bottom:10px;padding:8px 10px;
                   background:rgba(30,58,138,.08);border-radius:8px;border:1px solid rgba(30,58,138,.18);flex-wrap:wrap">
        <span style="font-size:14px;color:#1E3A8A;font-weight:700">🏫 ${_hE(sc.name)}</span>
        <span style="font-size:13px;color:var(--tx-muted)">${_hE(sc.city)} · ${_hE(sc.code)}</span>
        <button onclick="HASR._schoolCtx=null;hasrTab('systems')"
          style="margin-right:auto;font-size:12.5px;padding:2px 8px;border-radius:999px;
                 background:#E0E7FF;color:#3730A3;border:none;cursor:pointer;font-family:Tajawal">✕ كل المدارس</button>
      </div>`
    : '';

  /* بنر معلومات النظام الرئيسي */
  const totSys = sysEntry?.total || 0;
  const tE=sysEntry?.excellent||0, tG=sysEntry?.good||0, tB=sysEntry?.bad||0, tD=sysEntry?.deteriorated||0;
  const bars=[{v:tE,c:'#10B981',l:'ممتاز'},{v:tG,c:'#3B82F6',l:'جيد'},{v:tB,c:'#F59E0B',l:'سئ'},{v:tD,c:'#EF4444',l:'متهالك'}];
  const barTot = totSys||1;

  body.innerHTML = `
    ${schoolBanner}
    <div class="hasr-igrid">
      <div class="hasr-ic" style="--hc:#1E3A8A">
        <div class="hasr-ic-lbl">إجمالي الأصول</div>
        <div class="hasr-ic-val">${totSys.toLocaleString('ar')}</div>
      </div>
      <div class="hasr-ic" style="--hc:#0E7490">
        <div class="hasr-ic-lbl">الأنظمة الفرعية</div>
        <div class="hasr-ic-val">${subs.length}</div>
      </div>
    </div>

    <div class="hasr-cbar" style="margin-bottom:8px">
      ${bars.filter(x=>x.v>0).map(x=>`<div class="hasr-cseg" style="flex:${x.v};background:${x.c}">${((x.v/barTot)*100).toFixed(0)}%</div>`).join('')}
    </div>
    <div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:14px">
      ${bars.map(x=>`<span style="font-size:13px;color:var(--tx-sec)">
        <span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:${x.c};margin-left:3px"></span>
        ${x.l}: <strong>${(x.v||0).toLocaleString('ar')}</strong>
      </span>`).join('')}
    </div>

    <div class="hasr-sec">الأنظمة الفرعية — اضغط لعرض التفاصيل</div>
    ${!subs.length
      ? '<div style="text-align:center;padding:20px;color:var(--tx-muted);font-size:14.5px">لا توجد أنظمة فرعية</div>'
      : subs.map(sub=>{
          const pct = ((sub.total/totAll)*100).toFixed(1);
          return `
          <div class="hasr-srow" onclick="hasrShowSubDetail('${_hE(mainSys)}','${_hE(sub.name)}')">
            <div style="flex:1">
              <div class="hasr-sname">${_hE(sub.name)}</div>
              <div style="display:flex;border-radius:5px;overflow:hidden;height:6px;background:var(--bd-light);margin-top:5px">
                ${sub.excellent>0?`<div style="flex:${sub.excellent};background:#10B981"></div>`:''}
                ${sub.good>0?`<div style="flex:${sub.good};background:#3B82F6"></div>`:''}
                ${sub.bad>0?`<div style="flex:${sub.bad};background:#F59E0B"></div>`:''}
                ${sub.deteriorated>0?`<div style="flex:${sub.deteriorated};background:#EF4444"></div>`:''}
              </div>
              <div class="hasr-smeta" style="margin-top:3px">${sub.total.toLocaleString('ar')} أصل · ${pct}%</div>
            </div>
            <div class="hasr-sbadge">${(sub.total||0).toLocaleString('ar')}</div>
          </div>`;
        }).join('')}
  `;
}

/* ════════════════════════════════════════════════════════════════
   عرض تفاصيل النظام الفرعي — بدون فلترة، يفضل البانل مفتوح
════════════════════════════════════════════════════════════════ */
function hasrShowSubDetail(mainSys, subSys) {
  const ctx  = HASR._ctx;
  const sc   = HASR._schoolCtx;

  /* نجيب بيانات النظام الفرعي */
  let subObj;
  if (sc) {
    const rawSchool = (HASR.data?.schools||[]).find(s=>s.code===sc.code);
    const sysEntry  = (rawSchool?.systems||[]).find(s=>s.name===mainSys);
    subObj = (sysEntry?.subSystems||[]).find(s=>s.name===subSys);
  } else {
    const sysEntry = ctx.systems.find(s=>s.name===mainSys) ||
                     (HASR.data?.systems||[]).find(s=>s.name===mainSys);
    subObj = (sysEntry?.subSystems||[]).find(s=>s.name===subSys);
  }

  const tot  = subObj?.total || 0;
  const tE=subObj?.excellent||0, tG=subObj?.good||0, tB=subObj?.bad||0, tD=subObj?.deteriorated||0;
  const bars=[{v:tE,c:'#10B981',l:'ممتاز'},{v:tG,c:'#3B82F6',l:'جيد'},{v:tB,c:'#F59E0B',l:'سئ'},{v:tD,c:'#EF4444',l:'متهالك'}];
  const barTot = tot||1;
  const body = document.getElementById('hasr-spr-body');
  if (!body) return;

  _hS('hasr-spr-title', '🔩 ' + subSys);
  const spSub = document.getElementById('hasr-spr-sub');
  if (spSub) spSub.textContent = mainSys + (sc ? ' · 🏫 ' + sc.name : '');

  body.innerHTML = `
    <button class="hasr-back-btn" onclick="hasrSelectMainSystem('${_hE(mainSys)}')">← رجوع لـ ${_hE(mainSys)}</button>

    <div class="hasr-igrid">
      <div class="hasr-ic full" style="--hc:#0E7490">
        <div class="hasr-ic-lbl">${_hE(subSys)}</div>
        <div class="hasr-ic-val">${tot.toLocaleString('ar')}</div>
        <div class="hasr-ic-sub">إجمالي الأصول</div>
      </div>
    </div>

    <div class="hasr-sec">توزيع الحالة</div>
    <div class="hasr-cbar" style="margin-bottom:8px">
      ${bars.filter(x=>x.v>0).map(x=>`<div class="hasr-cseg" style="flex:${x.v};background:${x.c}">${((x.v/barTot)*100).toFixed(0)}%</div>`).join('')}
    </div>
    <div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:16px">
      ${bars.map(x=>`<span style="font-size:13px;color:var(--tx-sec)">
        <span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:${x.c};margin-left:3px"></span>
        ${x.l}: <strong>${(x.v||0).toLocaleString('ar')}</strong>
      </span>`).join('')}
    </div>

    <div class="hasr-sec">النظام الرئيسي</div>
    <div style="padding:10px 12px;background:rgba(30,58,138,.06);border-radius:8px;border:1px solid rgba(30,58,138,.15)">
      <span style="font-size:14.5px;font-weight:700;color:#1E3A8A">⚙️ ${_hE(mainSys)}</span>
    </div>
    ${sc ? `
    <div class="hasr-sec" style="margin-top:12px">المدرسة</div>
    <div style="padding:10px 12px;background:${CSS_TOKENS.α(CSS_TOKENS.info(),.06)};border-radius:8px;border:1px solid ${CSS_TOKENS.α(CSS_TOKENS.info(),.18)}">
      <div style="font-size:14.5px;font-weight:700;color:#0E7490">🏫 ${_hE(sc.name)}</div>
      <div style="font-size:13px;color:var(--tx-muted);margin-top:2px">${_hE(sc.city)} · ${_hE(sc.code)}</div>
    </div>` : ''}
  `;
}

/* اختيار نظام فرعي من تاب الفرعية العام — يعرض معلومات بدون فلترة */
function hasrSelectSubSystem(mainSys, subSys) {
  hasrShowSubDetail(mainSys, subSys);
}

/* رجوع لقائمة الأنظمة الرئيسية */
function hasrBackToSystems() {
  const tabsEl = document.querySelector('#hasr-sp .hasr-tabs');
  if (tabsEl) tabsEl.style.display = '';
  _hS('hasr-sp-title', '📦 حصر الأصول');
  const spSub = document.getElementById('hasr-sp-sub');
  if (spSub) spSub.textContent = HASR._schoolCtx ? ('🏫 ' + HASR._schoolCtx.name) : '';
  hasrTab('systems');
}

/* ════════════════════════════════════════════════════════════════
   بانيل تفاصيل مدرسة — يقرأ من HASR.data.schools مباشرة (الاستثناء الوحيد)
   لأنه يعرض البيانات الكاملة للمدرسة بكل أنظمتها بغض النظر عن الفلتر
════════════════════════════════════════════════════════════════ */
function hasrOpenDetail(code) {
  if (!HASR.data) return;
  const sc = HASR.data.schools.find(x=>x.code===code);
  if (!sc) return;
  _hS('hasr-dp-title', sc.name);
  _hS('hasr-dp-sub',   'كود: ' + sc.code + ' · ' + sc.city);
  const tot=sc.totalAssets||1;
  const bars=[{v:sc.excellent,c:'#10B981',l:'ممتاز'},{v:sc.good,c:'#3B82F6',l:'جيد'},{v:sc.bad,c:'#F59E0B',l:'سئ'},{v:sc.deteriorated,c:'#EF4444',l:'متهالك'}];
  const active=(sc.systems||[]).filter(s=>s.total>0);
  document.getElementById('hasr-dp-body').innerHTML=`
    <div class="hasr-igrid">
      <div class="hasr-ic" style="--hc:#059669"><div class="hasr-ic-lbl">الأصول</div><div class="hasr-ic-val">${(sc.totalAssets||0).toLocaleString('ar')}</div></div>
      <div class="hasr-ic" style="--hc:#1D4ED8"><div class="hasr-ic-lbl">المباني</div><div class="hasr-ic-val">${sc.buildings||0}</div></div>
      <div class="hasr-ic" style="--hc:#7C3AED"><div class="hasr-ic-lbl">الغرف</div><div class="hasr-ic-val">${sc.rooms||0}</div></div>
      <div class="hasr-ic" style="--hc:${sc.reassessed==='نعم'?'#7C3AED':'#94A3B8'}"><div class="hasr-ic-lbl">معادة</div><div class="hasr-ic-val" style="font-size:15.5px">${sc.reassessed==='نعم'?'✓ نعم':'لا'}</div></div>
    </div>
    <div class="hasr-sec">توزيع الحالة</div>
    <div class="hasr-cbar">
      ${bars.filter(x=>x.v>0).map(x=>`<div class="hasr-cseg" style="flex:${x.v};background:${x.c}">${((x.v/tot)*100).toFixed(0)}%</div>`).join('')}
    </div>
    <div style="display:flex;gap:12px;flex-wrap:wrap;margin-bottom:14px">
      ${bars.map(x=>`<span style="font-size:13px;color:var(--tx-sec)"><span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:${x.c};margin-left:3px"></span>${x.l}: <strong>${(x.v||0).toLocaleString('ar')}</strong></span>`).join('')}
    </div>
    <div class="hasr-sec" style="display:flex;align-items:center;justify-content:space-between">
      <span>الأنظمة الرئيسية</span>
      ${active.length?`<button onclick="hasrOpenSchoolSystems('${_hE(sc.code)}')" style="font-size:12.5px;padding:3px 9px;border-radius:6px;background:#1E3A8A;color:#fff;border:none;cursor:pointer;font-family:Tajawal">⚙️ عرض الكل</button>`:''}
    </div>
    ${!active.length
      ?'<div style="color:var(--tx-muted);font-size:14.5px;text-align:center;padding:16px">لا توجد أصول</div>'
      :active.map(s=>`
        <div class="hasr-srow" onclick="hasrOpenSchoolSystems('${_hE(sc.code)}','${_hE(s.name)}')" style="padding:9px 0;border-bottom:1px solid var(--bd-light)">
          <div style="flex:1">
            <div style="display:flex;justify-content:space-between;margin-bottom:5px">
              <span style="font-size:14.5px;font-weight:700;color:var(--tx-main)">${_hE(s.name)}</span>
              <span style="font-size:14px;font-weight:700;background:#EFF6FF;color:#1D4ED8;padding:2px 8px;border-radius:6px">${s.total}</span>
            </div>
            <div style="display:flex;border-radius:5px;overflow:hidden;height:9px;background:var(--bd-light)">
              ${s.excellent>0?`<div style="flex:${s.excellent};background:#10B981"></div>`:''}
              ${s.good>0?`<div style="flex:${s.good};background:#3B82F6"></div>`:''}
              ${s.bad>0?`<div style="flex:${s.bad};background:#F59E0B"></div>`:''}
              ${s.deteriorated>0?`<div style="flex:${s.deteriorated};background:#EF4444"></div>`:''}
            </div>
          </div>
          <div style="font-size:13px;color:var(--tx-muted);padding-right:6px">← تفاصيل</div>
        </div>`).join('')}
  `;
  document.getElementById('hasr-dp').classList.add('hasr-open');
}

function hasrOpenSchoolSystems(code, sysName) {
  if (!HASR.data) return;
  const school=(HASR.data.schools||[]).find(s=>s.code===code);
  if (!school) return;
  HASR._schoolCtx={code:school.code,name:school.name,city:school.city,systems:school.systems||[]};
  _hasrOpenSP('systems');
  if (sysName) setTimeout(()=>hasrSelectMainSystem(sysName),60);
}

/* ════════════════════════════════════════════════════════════════
   الرسوم البيانية — تقرأ من HASR._ctx فقط
════════════════════════════════════════════════════════════════ */
function _hasrFillFilters() {
  /* نملأ من HASR.data.schools لضمان ظهور كل المدن دائماً */
  const cities=[...new Set((HASR.data.schools||[]).map(sc=>sc.city).filter(Boolean))].sort();
  const opts='<option value="">— الكل —</option>'+cities.map(c=>`<option value="${_hE(c)}">${_hE(c)}</option>`).join('');
  /* الآن في فلتر موحد واحد فقط */
  const e=document.getElementById('hasr-global-city');
  if(e)e.innerHTML=opts;
}

/* نقطة الدخول من شريط الفلاتر الموحد */
/* debounce للبحث في حصر الأصول — مثل debounceFilter في الداشبورد الرئيسي */
let _hasrSearchTimer = null;
function hasrDebounceFilter() {
  clearTimeout(_hasrSearchTimer);
  _hasrSearchTimer = setTimeout(_hasrApplyFilters, 300);
}

function hasrGlobalFilterChanged() {
  _hasrApplyFilters();
}

function _hasrChartCondition() {
  const ctx=document.getElementById('hasr-ch-condition'); if(!ctx)return;
  const s=HASR._ctx?.summary||{};
  const E=s.excellent||0, G=s.good||0, B=s.bad||0, D=s.deteriorated||0;
  if(HASR.charts?.cond){HASR.charts.cond.destroy();}
  HASR.charts.cond=new Chart(ctx,{
    type:'doughnut',
    data:{labels:['ممتاز','جيد','سئ','متهالك'],datasets:[{data:[E,G,B,D],backgroundColor:['#10B981','#3B82F6','#F59E0B','#EF4444'],borderWidth:2,borderColor:'#fff'}]},
    options:{responsive:true,maintainAspectRatio:false,cutout:'62%',
      plugins:{legend:{position:'bottom',labels:{font:{family:'Tajawal',size:11},padding:14}},
        tooltip:{callbacks:{label:c=>{const t=E+G+B+D;return ` ${c.raw.toLocaleString('ar')} أصل (${t>0?((c.raw/t)*100).toFixed(1):0}%)`;}}}}}}
  );
}

function _hasrChartSystems() {
  const ctx=document.getElementById('hasr-ch-systems'); if(!ctx)return;
  const top=(HASR._ctx?.chartSystems||[]).slice(0,10);
  if(HASR.charts?.sys){HASR.charts.sys.destroy();}
  HASR.charts.sys=new Chart(ctx,{
    type:'bar',
    data:{labels:top.map(s=>s.name),datasets:[{label:'إجمالي الأصول',data:top.map(s=>s.total),backgroundColor:'#3B82F6CC',borderColor:'#1D4ED8',borderWidth:1,borderRadius:4}]},
    options:{responsive:true,maintainAspectRatio:false,indexAxis:'y',
      layout:{padding:{right:8}},
      plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>` ${c.raw.toLocaleString('ar')} أصل`}}},
      scales:{
        x:{grid:{color:'rgba(0,0,0,.04)'},ticks:{font:{family:'Tajawal',size:10}}},
        y:{ticks:{font:{family:'Tajawal',size:10},autoSkip:false,maxRotation:0,callback:(v,i)=>top[i]?.name||''},
           afterFit(scale){scale.width=Math.max(scale.width,220);}}
      }}
  });
}

function _hasrChartCities() {
  const ctx=document.getElementById('hasr-ch-cities'); if(!ctx)return;
  const cities=HASR._ctx?.cities||[];
  if(HASR.charts?.cit){HASR.charts.cit.destroy();}
  HASR.charts.cit=new Chart(ctx,{
    type:'bar',
    data:{labels:cities.map(c=>c.city),datasets:[{label:'عدد المدارس',data:cities.map(c=>c.schools),backgroundColor:'#6366F1CC',borderColor:'#4F46E5',borderWidth:1,borderRadius:4}]},
    options:{responsive:true,maintainAspectRatio:false,
      plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>` ${c.raw.toLocaleString('ar')} مدرسة`}}},
      scales:{x:{ticks:{font:{family:'Tajawal',size:10}}},y:{grid:{color:'rgba(0,0,0,.04)'},ticks:{font:{family:'Tajawal',size:10}}}}}
  });
}

/* ════════════════════════════════════════════════════════════════
   جدول المدارس — يقرأ من HASR._ctx.schools
════════════════════════════════════════════════════════════════ */
function renderHasrTable() {
  if(!HASR._ctx)return;
  /* schools في _ctx مفلترة بالفعل بكل الفلاتر بما فيها البحث */
  const sc   = HASR._ctx.schools;
  const sort = document.getElementById('hasr-sort')?.value||'assets_desc';

  let list=sc.slice();
  list.sort((a,b)=>sort==='assets_desc'?b.totalAssets-a.totalAssets:sort==='assets_asc'?a.totalAssets-b.totalAssets:sort==='name'?a.name.localeCompare(b.name,'ar'):a.city.localeCompare(b.city,'ar'));
  HASR.filtered=list; HASR.page=0;
  _hS('hasr-tbl-count',list.length.toLocaleString('ar')+' مدرسة');
  _hasrDrawTbl();
}

function _hasrDrawTbl(){
  const list=HASR.filtered,st=HASR.page*HASR_PAGE_SIZE;
  const tb=document.getElementById('hasr-tbl-body');if(!tb)return;
  /* الحالة المفلترة حالياً — عشان نبرز العمود المناسب */
  const activeCond = document.getElementById('hasr-global-condition')?.value || '';
  const condStyles = {
    excellent:  { color:'#059669', bg:'#DCFCE7', border:'#86EFAC' },
    good:       { color:'#1D4ED8', bg:'#DBEAFE', border:'#93C5FD' },
    bad:        { color:'#D97706', bg:'#FEF3C7', border:'#FCD34D' },
    deteriorated:{ color:'#DC2626', bg:'#FEE2E2', border:'#FCA5A5' }
  };
  const makeCell = (val, key) => {
    const isActive = activeCond === key;
    const s = condStyles[key];
    if (isActive) {
      return `<td style="font-weight:800;color:${s.color};background:${s.bg};
        border:1.5px solid ${s.border};border-radius:6px;padding:4px 8px;text-align:center">
        ${val||0}
        <div style="font-size:9px;font-weight:700;opacity:.7;margin-top:1px">▲ نشط</div>
      </td>`;
    }
    return `<td style="color:${s.color};font-weight:600;opacity:${activeCond?'.45':'1'}">${val||0}</td>`;
  };
  tb.innerHTML=list.slice(st,st+HASR_PAGE_SIZE).map(sc=>{
    const r=sc.reassessed==='نعم';
    const rowHighlight = activeCond ? `background:rgba(${activeCond==='excellent'?'5,150,105':activeCond==='good'?'29,78,216':activeCond==='bad'?'217,119,6':'220,38,38'},.03)` : '';
    return `<tr style="cursor:pointer;${rowHighlight}" onclick="hasrOpenDetail('${_hE(sc.code)}')">
      <td style="text-align:right;padding-right:14px;font-weight:600">${_hE(sc.name)}</td>
      <td style="font-family:monospace;font-size:11px">${_hE(sc.code)}</td>
      <td>${_hE(sc.city)}</td>
      <td style="font-weight:700">${(sc.totalAssets||0).toLocaleString('ar')}</td>
      ${makeCell(sc.excellent,   'excellent')}
      ${makeCell(sc.good,        'good')}
      ${makeCell(sc.bad,         'bad')}
      ${makeCell(sc.deteriorated,'deteriorated')}
      <td>${sc.buildings||0}</td><td>${sc.rooms||0}</td>
      <td><span style="font-size:10px;padding:2px 8px;border-radius:999px;font-weight:700;background:${r?'#EDE9FE':'#F1F5F9'};color:${r?'#6D28D9':'#64748B'}">${r?'✓ معادة':'لا'}</span></td>
      <td style="white-space:nowrap">
        <button onclick="event.stopPropagation();hasrOpenDetail('${_hE(sc.code)}')"
          style="font-size:10px;padding:3px 8px;border-radius:6px;cursor:pointer;background:#EFF6FF;color:#1D4ED8;border:1px solid #BFDBFE;font-family:Tajawal">عرض ←</button>
        <button onclick="event.stopPropagation();hasrOpenSchoolSystems('${_hE(sc.code)}')"
          style="font-size:10px;padding:3px 8px;border-radius:6px;cursor:pointer;background:#EDE9FE;color:#5B21B6;border:1px solid #C4B5FD;font-family:Tajawal;margin-right:4px">⚙️ أنظمتها</button>
      </td>
    </tr>`;
  }).join('');
  const pag=document.getElementById('hasr-pag'),pages=Math.ceil(list.length/HASR_PAGE_SIZE);
  if(!pag)return;if(pages<=1){pag.innerHTML='';return;}
  let h=`<span class="pag-info">صفحة ${HASR.page+1} من ${pages}</span><div class="pag-btns">`;
  h+=`<button class="pag-btn" ${HASR.page===0?'disabled':''} onclick="HASR.page--;_hasrDrawTbl()">→ السابق</button>`;
  let s2=Math.max(0,HASR.page-3),e2=Math.min(pages-1,s2+6);if(e2-s2<6)s2=Math.max(0,e2-6);
  for(let p=s2;p<=e2;p++)h+=`<button class="pag-btn${p===HASR.page?' active':''}" onclick="HASR.page=${p};_hasrDrawTbl()">${p+1}</button>`;
  h+=`<button class="pag-btn" ${HASR.page===pages-1?'disabled':''} onclick="HASR.page++;_hasrDrawTbl()">← التالي</button></div>`;
  pag.innerHTML=h;
}

/* ════════════════════════════════════════════════════════════════
   مسح الفلاتر
════════════════════════════════════════════════════════════════ */
function hasrClearSubFilter(){
  HASR._filterMain=''; HASR._filterSub='';
  _hasrApplyFilters();
}

function clearHasrFilters(){
  ['hasr-global-city','hasr-global-condition','hasr-global-reassessed']
    .forEach(id=>{const e=document.getElementById(id);if(e)e.value='';});
  const sr=document.getElementById('hasr-global-search');if(sr)sr.value='';
  const so=document.getElementById('hasr-sort');if(so)so.value='assets_desc';
  HASR._filterMain=''; HASR._filterSub='';
  _hasrApplyFilters();
}

/* للاستدعاء من sysBrowseSelectSub في قسم الأنظمة الرئيسية — تمت إزالة
   النسخة الخاطئة هنا (كانت تربط الأنظمة الرئيسية بتبويب حصر الأصول
   وهما تبويبان مستقلان لا علاقة بينهما) */

/* ════════════════════════════════════════════════════════════════
   مساعدات
════════════════════════════════════════════════════════════════ */
function exportHasrCSV(){
  if(!HASR._ctx){alert('لا توجد بيانات');return;}
  const h=['اسم المدرسة','كود المدرسة','المدينة','إجمالي الأصول','ممتاز','جيد','سئ','متهالك','مباني','غرف','معادة'];
  const src=HASR.filtered.length>0?HASR.filtered:HASR._ctx.schools;
  const rows=src.map(sc=>[sc.name,sc.code,sc.city,sc.totalAssets,sc.excellent,sc.good,sc.bad,sc.deteriorated,sc.buildings,sc.rooms,sc.reassessed].map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(','));
  const a=Object.assign(document.createElement('a'),{href:URL.createObjectURL(new Blob(['\uFEFF'+[h.join(','),...rows].join('\n')],{type:'text/csv;charset=utf-8;'})),download:'حصر_الأصول.csv'});
  a.click();
}
function _hasrShowLoading(on){
  const ld=document.getElementById('hasr-loading'),er=document.getElementById('hasr-error');
  if(ld)ld.style.display=on?'block':'none';if(er)er.style.display='none';
}
function _hasrShowError(msg){
  const ld=document.getElementById('hasr-loading');if(ld)ld.style.display='none';
  const er=document.getElementById('hasr-error');if(er)er.style.display='block';
  _hS('hasr-error-msg',msg);
}
function _hS(id,v){const e=document.getElementById(id);if(e)e.textContent=v;}
function _hW(id,w){const e=document.getElementById(id);if(e)e.style.width=w;}
function _hE(s){return String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}


/* ════════════════════════════════════════════════════════════════════
   👥  تبويب تقييم الموظفين — tab-emp-kpi                            ║
   ════════════════════════════════════════════════════════════════════
   المصدر : window.RAW_EMP_KPI  ← شيت "تقييم_الموظفين" في Google Sheet
   المفتاح: d.employeeKpi  (يُعيَّن في loadData عبر sa(d.employeeKpi))

   ┌─ شرح الأعمدة ──────────────────────────────────────────────────┐
   │  اسم الموظف       : الاسم الكامل                                │
   │  الدور            : المسمى الوظيفي (FMA مثلاً)                  │
   │  المنطقة          : المنطقة الجغرافية (جدة / مكة / المدينة / الطائف)│
   │  المسند           : إجمالي المهام المسندة للموظف                │
   │  المنجَز          : عدد المهام التي أنجزها فعلاً                 │
   │  الإنجاز %        : (المنجَز / المسند) × 100                     │
   │  توثيق بالصور %   : نسبة رفع صور لتوثيق المهام                  │
   │  التعليقات %      : نسبة إضافة تعليقات على المهام                │
   │  جودة التقرير %   : جودة التقارير المرفوعة                       │
   │  وقت الزيارة %    : الالتزام بوقت الزيارة الميدانية              │
   │  الدرجة           : الدرجة الكلية من 100 (مرجّحة من المؤشرات أعلاه)│
   │  التقدير          : ممتاز / جيد جداً / جيد / يحتاج تحسين / ضعيف  │
   └────────────────────────────────────────────────────────────────┘

   ⚠️  AI MAINTAINER NOTE — اقرأ هذا قبل أي تعديل:
   ══════════════════════════════════════════════════════════════════
   إذا أضفت أعمدة جديدة لشيت تقييم_الموظفين، أو غيّرت أسماء الأعمدة،
   أو غيّرت طريقة حساب الدرجة، يجب عليك تحديث:
     1. دالة renderEmpKpiTab()   ← أعمدة الجدول + الـ KPIs
     2. دالة _empKpiDrawCharts() ← مفاتيح metricKeys
     3. دالة _empKpiRender()     ← منطق الفلترة والترتيب
     4. قسم summary.تقييم_الموظفين في دالة _fcbBuildSummary()
        (قرب نهاية قسم الشاتبوت — ابحث عن "تقييم_الموظفين")
        لأن الشاتبوت يقرأ منه — بدون تحديثه لن يعرف البيانات الجديدة.
   ══════════════════════════════════════════════════════════════════ */

const EMP_KPI = {
  page: 0,
  pageSize: 20,
  filtered: [],
  charts: {},
  _region: '',
  _role: '',
  _grade: '',
  _search: '',
  _sort: 'score_desc',
};
window.EMP_KPI = EMP_KPI;

/* ── ألوان التقديرات ── */
const EMP_GRADE_COLORS = {
  'ممتاز':        { bg: '#F0FDF4', color: '#15803D', border: '#86EFAC' },
  'جيد جداً':     { bg: '#ECFDF5', color: '#059669', border: '#6EE7B7' },
  'جيد':          { bg: '#EFF6FF', color: '#1D4ED8', border: '#93C5FD' },
  'يحتاج تحسين':  { bg: '#FFFBEB', color: '#D97706', border: '#FCD34D' },
  'ضعيف':         { bg: '#FEF2F2', color: '#DC2626', border: '#FCA5A5' },
};
const EMP_GRADE_ORDER = ['ممتاز', 'جيد جداً', 'جيد', 'يحتاج تحسين', 'ضعيف'];

/* ── مساعد destroy آمن مع فحص داتا ── */
function _empSafeDestroyChart(key) {
  const ch = EMP_KPI.charts[key];
  if (!ch) return;
  try { ch.destroy(); } catch (_) {}
  delete EMP_KPI.charts[key];
}

/* ════ الدالة الرئيسية ════ */
function renderEmpKpiTab() {
  const el = document.getElementById('emp-kpi-content');
  if (!el) return;

  const rows = window.RAW_EMP_KPI || [];
  if (!rows.length) {
    el.innerHTML = `
      <div class="card" style="text-align:center;padding:60px 24px">
        <div style="font-size:48px;margin-bottom:12px">👥</div>
        <div style="font-size:16px;font-weight:700;color:var(--tx-main)">لا توجد بيانات تقييم موظفين</div>
        <div style="font-size:12px;color:var(--tx-muted);margin-top:8px">
          تأكد من وجود شيت "تقييم_الموظفين" في ملف البيانات وأن الـ Apps Script يقرأها
        </div>
      </div>`;
    return;
  }

  const n_  = v => { const x = parseFloat(String(v||'').replace(/%/g,'').replace(/,/g,'')); return isNaN(x) ? 0 : x; };
  const str = v => String(v||'').trim();
  const pct = (v, total) => total ? ((v/total)*100).toFixed(1)+'%' : '0%';

  /* ── إحصاءات عامة ── */
  const total      = rows.length;
  const regions    = [...new Set(rows.map(r=>str(r['المنطقة'])).filter(Boolean))].sort();
  const roles      = [...new Set(rows.map(r=>str(r['الدور'])).filter(Boolean))].sort();
  const avgScore   = (rows.reduce((s,r)=>s+n_(r['الدرجة']),0)/total).toFixed(1);
  const gradeCount = {};
  EMP_GRADE_ORDER.forEach(g => { gradeCount[g] = rows.filter(r=>str(r['التقدير'])===g).length; });

  /* ── مؤشرات كل موظف ── */
  const METRIC_KEYS    = ['الإنجاز %','توثيق بالصور %','التعليقات %','جودة التقرير %','وقت الزيارة %'];
  const METRIC_LABELS  = ['الإنجاز','توثيق بالصور','التعليقات','جودة التقرير','وقت الزيارة'];
  const METRIC_DESC    = [
    'نسبة المهام المنجَزة من المسندة',
    'نسبة توثيق المهام بالصور',
    'نسبة إضافة تعليقات على المهام',
    'جودة التقارير المرفوعة',
    'الالتزام بوقت الزيارة الميدانية',
  ];

  /* ── بناء الصفحة ── */
  el.innerHTML = `

  <!-- ══ شريط العنوان ══ -->
  <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px;margin-bottom:14px">
    <div style="display:flex;align-items:center;gap:12px">
      <span style="font-size:26px">👥</span>
      <div>
        <div style="font-size:15px;font-weight:800;color:var(--tx-main)">لوحة تقييم أداء الموظفين</div>
        <div style="font-size:11px;color:var(--tx-muted)">
          ${total.toLocaleString('ar')} موظف · ${regions.length} منطقة · الدرجة من 100
        </div>
      </div>
    </div>
    <div style="display:flex;gap:8px;align-items:center">
      <!-- أسطورة التقديرات -->
      <div style="display:flex;gap:6px;flex-wrap:wrap">
        ${EMP_GRADE_ORDER.map(g => {
          const s = EMP_GRADE_COLORS[g];
          return `<span style="font-size:10px;font-weight:700;padding:3px 10px;border-radius:999px;
            background:${s.bg};color:${s.color};border:1px solid ${s.border}">${g}</span>`;
        }).join('')}
      </div>
      <button class="export-btn export-btn-csv" onclick="_empKpiExportCSV()" style="font-size:11px">⬇ تصدير CSV</button>
    </div>
  </div>

  <!-- ══ توضيح نظام التقييم ══ -->
  <div style="padding:12px 16px;margin-bottom:14px;border-radius:12px;
       background:linear-gradient(135deg,#EFF6FF 0%,#F0FDF4 100%);
       border:1.5px solid #BFDBFE">
    <div style="font-size:11px;font-weight:800;color:#1D4ED8;margin-bottom:8px">📋 كيف يُحسب التقييم؟</div>
    <div style="display:flex;gap:10px;flex-wrap:wrap">
      ${METRIC_KEYS.map((k,i) => `
        <div style="font-size:10px;color:var(--tx-sec);background:#fff;padding:4px 10px;
             border-radius:8px;border:1px solid #E2E8F0;white-space:nowrap">
          <strong>${METRIC_LABELS[i]}</strong> — ${METRIC_DESC[i]}
        </div>`).join('')}
    </div>
    <div style="font-size:10px;color:var(--tx-muted);margin-top:8px">
      الدرجة الكلية = متوسط مرجّح للمؤشرات الخمسة أعلاه · التقدير: ممتاز ≥85 · جيد جداً 70-84 · جيد 55-69 · يحتاج تحسين 40-54 · ضعيف &lt;40
    </div>
  </div>

  <!-- ══ فلاتر موحدة ══ -->
  <div style="display:flex;align-items:flex-end;gap:10px;flex-wrap:wrap;padding:14px 16px;
       margin-bottom:14px;border-radius:14px;background:var(--bg-2,#f8fafc);border:1.5px solid var(--bd-light,#e2e8f0)">
    <div class="fg" style="margin:0;min-width:130px">
      <div class="fg-lbl">المنطقة</div>
      <select class="fsel" id="emp-filter-region"
        onchange="EMP_KPI._region=this.value;EMP_KPI.page=0;_empKpiRender()">
        <option value="">— الكل —</option>
        ${regions.map(r=>`<option value="${r}">${r}</option>`).join('')}
      </select>
    </div>
    <div class="fg" style="margin:0;min-width:110px">
      <div class="fg-lbl">الدور</div>
      <select class="fsel" id="emp-filter-role"
        onchange="EMP_KPI._role=this.value;EMP_KPI.page=0;_empKpiRender()">
        <option value="">— الكل —</option>
        ${roles.map(r=>`<option value="${r}">${r}</option>`).join('')}
      </select>
    </div>
    <div class="fg" style="margin:0">
      <div class="fg-lbl">التقدير</div>
      <select class="fsel" id="emp-filter-grade"
        onchange="EMP_KPI._grade=this.value;EMP_KPI.page=0;_empKpiRender()">
        <option value="">— الكل —</option>
        ${EMP_GRADE_ORDER.map(g=>`<option value="${g}">${g}</option>`).join('')}
      </select>
    </div>
    <div class="fg" style="margin:0;flex:1;min-width:180px">
      <div class="fg-lbl">بحث بالاسم</div>
      <input class="finp" id="emp-search" placeholder="اسم الموظف..."
        oninput="EMP_KPI._search=this.value;EMP_KPI.page=0;_empKpiRender()">
    </div>
    <div class="fg" style="margin:0">
      <div class="fg-lbl">ترتيب</div>
      <select class="fsel" id="emp-sort"
        onchange="EMP_KPI._sort=this.value;EMP_KPI.page=0;_empKpiRender()">
        <option value="score_desc">الدرجة الكلية ↓</option>
        <option value="score_asc">الدرجة الكلية ↑</option>
        <option value="completion_desc">الإنجاز ↓</option>
        <option value="name">الاسم أ-ي</option>
      </select>
    </div>
    <button class="f-clear" onclick="_empKpiClearFilters()" style="margin:0;align-self:flex-end">✕ مسح</button>
  </div>

  <!-- ══ KPIs ══ -->
  <div class="kpi-grid" style="margin-bottom:14px;grid-template-columns:repeat(4,minmax(0,1fr))">
    <div class="kpi kc-blue">
      <div class="kpi-val" id="emp-k-total">${total.toLocaleString('ar')}</div>
      <div class="kpi-lbl">إجمالي الموظفين</div>
      <div class="kpi-sub" id="emp-k-regions">${regions.length} منطقة</div>
    </div>
    <div class="kpi kc-teal">
      <div class="kpi-val" id="emp-k-avg">${avgScore}</div>
      <div class="kpi-lbl">متوسط الدرجة الكلية</div>
      <div class="kpi-sub">من 100</div>
    </div>
    <div class="kpi kc-green">
      <div class="kpi-val" id="emp-k-excellent">${gradeCount['ممتاز']||0}</div>
      <div class="kpi-lbl">ممتاز ≥ 85</div>
      <div class="kpi-sub" id="emp-k-excellent-pct">${pct(gradeCount['ممتاز']||0, total)} من الإجمالي</div>
    </div>
    <div class="kpi kc-red">
      <div class="kpi-val" id="emp-k-weak">${gradeCount['ضعيف']||0}</div>
      <div class="kpi-lbl">ضعيف &lt; 40</div>
      <div class="kpi-sub" id="emp-k-weak-pct">${pct(gradeCount['ضعيف']||0, total)} من الإجمالي</div>
    </div>
  </div>

  <!-- ══ الرسوم البيانية ══ -->
  <div class="g2 mb14">
    <div class="card">
      <div class="card-title">
        <span class="card-title-icon" style="background:#F0FDF4;color:#059669"><svg class="cti-svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><circle cx="12" cy="12" r="1"/></svg></span>
        توزيع التقديرات
        <span class="sub">من إجمالي ${total} موظف</span>
      </div>
      <div class="chart-box" style="height:240px"><canvas id="emp-ch-grades"></canvas></div>
    </div>
    <div class="card">
      <div class="card-title">
        <span class="card-title-icon" style="background:#EFF6FF;color:#1D4ED8"><svg class="cti-svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect width="7" height="7" x="3" y="3" rx="1"/><rect width="7" height="7" x="14" y="3" rx="1"/><rect width="7" height="7" x="14" y="14" rx="1"/><rect width="7" height="7" x="3" y="14" rx="1"/></svg></span>
        متوسط الدرجة الكلية حسب المنطقة
        <span class="sub">الدرجة من 100</span>
      </div>
      <div class="chart-box" style="height:240px"><canvas id="emp-ch-regions"></canvas></div>
    </div>
  </div>

  <div class="card mb14">
    <div class="card-title">
      <span class="card-title-icon" style="background:#FFF7ED;color:#C2410C"><svg class="cti-svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 5h.01"/><path d="M3 12h.01"/><path d="M3 19h.01"/><path d="M8 5h13"/><path d="M8 12h13"/><path d="M8 19h13"/></svg></span>
      متوسط المؤشرات الخمسة — مقارنة شاملة
      <span class="sub">كل مؤشر من 100%</span>
    </div>
    <div class="chart-box" style="height:260px"><canvas id="emp-ch-metrics"></canvas></div>
  </div>

  <!-- ══ جدول الموظفين ══ -->
  <div class="card mb14">
    <div class="card-title">
      <span class="card-title-icon" style="background:#F0F9FF;color:#0369A1"><svg class="cti-svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3v18"/><rect width="18" height="18" x="3" y="3" rx="2"/><path d="M3 9h18"/><path d="M3 15h18"/></svg></span>
      تفاصيل الموظفين
      <span class="sub" id="emp-tbl-count"></span>
    </div>

    <!-- أعمدة الجدول + شرحها -->
    <div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px;padding:8px 12px;
         background:var(--bg-2,#f8fafc);border-radius:8px;border:1px solid var(--bd-light)">
      <span style="font-size:10px;color:var(--tx-muted);font-weight:700">شرح الأعمدة:</span>
      <span style="font-size:10px;color:var(--tx-sec)">المسند = إجمالي المهام</span>
      <span style="font-size:10px;color:var(--tx-muted)">·</span>
      <span style="font-size:10px;color:var(--tx-sec)">المنجَز = أُنجز فعلاً</span>
      <span style="font-size:10px;color:var(--tx-muted)">·</span>
      <span style="font-size:10px;color:var(--tx-sec)">الدرجة = متوسط المؤشرات المرجّح</span>
    </div>

    <div class="tbl-wrap">
      <table>
        <thead>
          <tr>
            <th style="min-width:180px;text-align:right;padding-right:14px">الموظف</th>
            <th>المنطقة</th>
            <th title="إجمالي المهام المسندة">المسند</th>
            <th title="المهام المنجَزة" style="color:#059669">المنجَز</th>
            <th title="نسبة الإنجاز = المنجَز ÷ المسند">الإنجاز %</th>
            <th title="نسبة توثيق المهام بالصور">توثيق بالصور</th>
            <th title="نسبة إضافة تعليقات">التعليقات</th>
            <th title="جودة التقارير المرفوعة">جودة التقرير</th>
            <th title="الالتزام بوقت الزيارة">وقت الزيارة</th>
            <th style="min-width:70px" title="الدرجة الكلية المرجّحة من 100">الدرجة</th>
            <th style="min-width:100px">التقدير</th>
          </tr>
        </thead>
        <tbody id="emp-tbl-body"></tbody>
      </table>
    </div>
    <div class="pag-bar" id="emp-pag" style="margin-top:8px"></div>
  </div>`;

  _empKpiDrawCharts(rows);
  _empKpiRender();
}

/* ════ فلترة + تحديث KPIs + جدول ════ */
function _empKpiRender() {
  const rows = window.RAW_EMP_KPI || [];
  const n_  = v => { const x = parseFloat(String(v||'').replace(/%/g,'').replace(/,/g,'')); return isNaN(x)?0:x; };
  const str = v => String(v||'').trim();
  const q   = (EMP_KPI._search||'').trim().toLowerCase();

  let list = rows.filter(r => {
    if (EMP_KPI._region && str(r['المنطقة']) !== EMP_KPI._region) return false;
    if (EMP_KPI._role   && str(r['الدور'])   !== EMP_KPI._role)   return false;
    if (EMP_KPI._grade  && str(r['التقدير']) !== EMP_KPI._grade)  return false;
    if (q && !str(r['اسم الموظف']).toLowerCase().includes(q)) return false;
    return true;
  });

  list.sort((a,b) => {
    if (EMP_KPI._sort === 'score_desc')      return n_(b['الدرجة']) - n_(a['الدرجة']);
    if (EMP_KPI._sort === 'score_asc')       return n_(a['الدرجة']) - n_(b['الدرجة']);
    if (EMP_KPI._sort === 'completion_desc') return n_(b['الإنجاز %']) - n_(a['الإنجاز %']);
    return str(a['اسم الموظف']).localeCompare(str(b['اسم الموظف']),'ar');
  });

  EMP_KPI.filtered = list;
  const t = list.length;
  const avg = t ? (list.reduce((s,r)=>s+n_(r['الدرجة']),0)/t).toFixed(1) : '—';

  const gradeCountF = {};
  EMP_GRADE_ORDER.forEach(g => { gradeCountF[g] = list.filter(r=>str(r['التقدير'])===g).length; });

  const ge = id => document.getElementById(id);
  const set = (id,v) => { const e=ge(id); if(e) e.textContent=v; };
  set('emp-k-total',   t.toLocaleString('ar'));
  set('emp-k-regions', [...new Set(list.map(r=>str(r['المنطقة'])).filter(Boolean))].length + ' منطقة');
  set('emp-k-avg',     avg);
  set('emp-k-excellent', gradeCountF['ممتاز']||0);
  set('emp-k-excellent-pct', t?((gradeCountF['ممتاز']||0)/t*100).toFixed(1)+'%':'0%');
  set('emp-k-weak',    gradeCountF['ضعيف']||0);
  set('emp-k-weak-pct', t?((gradeCountF['ضعيف']||0)/t*100).toFixed(1)+'%':'0%');
  set('emp-tbl-count', t.toLocaleString('ar') + ' موظف');

  _empKpiDrawTable();
}

/* ════ جدول مع pagination ════ */
function _empKpiDrawTable() {
  const list = EMP_KPI.filtered;
  const st   = EMP_KPI.page * EMP_KPI.pageSize;
  const tb   = document.getElementById('emp-tbl-body');
  if (!tb) return;

  const n_  = v => { const x = parseFloat(String(v||'').replace(/%/g,'').replace(/,/g,'')); return isNaN(x)?0:x; };
  const str = v => String(v||'').trim();
  const fmt = v => n_(v).toFixed(1) + '%';

  const gradeStyle = g => {
    const s = EMP_GRADE_COLORS[g] || { bg:'#F1F5F9', color:'#64748B', border:'#CBD5E1' };
    return `background:${s.bg};color:${s.color};border:1px solid ${s.border}`;
  };
  const scoreStyle = sc => {
    const bg    = sc>=85?'#F0FDF4':sc>=70?'#ECFDF5':sc>=55?'#EFF6FF':sc>=40?'#FFFBEB':'#FEF2F2';
    const color = sc>=85?'#15803D':sc>=70?'#059669':sc>=55?'#1D4ED8':sc>=40?'#D97706':'#DC2626';
    return `background:${bg};color:${color}`;
  };

  tb.innerHTML = list.slice(st, st + EMP_KPI.pageSize).map(r => {
    const grade = str(r['التقدير']);
    const score = n_(r['الدرجة']);
    const done      = n_(r['المنجَز']);
    const assigned  = n_(r['المسند']);
    return `<tr>
      <td style="text-align:right;padding-right:14px">
        <div style="font-weight:700;font-size:12px">${str(r['اسم الموظف'])}</div>
        <div style="font-size:10px;color:var(--tx-muted)">${str(r['الدور'])}</div>
      </td>
      <td>${str(r['المنطقة'])}</td>
      <td style="font-weight:700;text-align:center">${assigned}</td>
      <td style="color:#059669;font-weight:700;text-align:center">${done}</td>
      <td style="text-align:center">${fmt(r['الإنجاز %'])}</td>
      <td style="text-align:center">${fmt(r['توثيق بالصور %'])}</td>
      <td style="text-align:center">${fmt(r['التعليقات %'])}</td>
      <td style="text-align:center">${fmt(r['جودة التقرير %'])}</td>
      <td style="text-align:center">${fmt(r['وقت الزيارة %'])}</td>
      <td style="font-weight:800;font-size:13px;${scoreStyle(score)};border-radius:6px;text-align:center;padding:4px 8px">${score.toFixed(1)}</td>
      <td><span style="font-size:11px;padding:3px 10px;border-radius:999px;font-weight:700;${gradeStyle(grade)}">${grade}</span></td>
    </tr>`;
  }).join('');

  /* pagination */
  const pag   = document.getElementById('emp-pag');
  const pages = Math.ceil(list.length / EMP_KPI.pageSize);
  if (!pag) return;
  if (pages <= 1) { pag.innerHTML = ''; return; }
  let h = `<span class="pag-info">صفحة ${EMP_KPI.page+1} من ${pages}</span><div class="pag-btns">`;
  h += `<button class="pag-btn" ${EMP_KPI.page===0?'disabled':''} onclick="EMP_KPI.page--;_empKpiDrawTable()">→ السابق</button>`;
  let s=Math.max(0,EMP_KPI.page-3), e=Math.min(pages-1,s+6);
  if(e-s<6) s=Math.max(0,e-6);
  for(let p=s;p<=e;p++) h+=`<button class="pag-btn${p===EMP_KPI.page?' active':''}" onclick="EMP_KPI.page=${p};_empKpiDrawTable()">${p+1}</button>`;
  h += `<button class="pag-btn" ${EMP_KPI.page===pages-1?'disabled':''} onclick="EMP_KPI.page++;_empKpiDrawTable()">← التالي</button></div>`;
  pag.innerHTML = h;
}

/* ════ الشارتات — مع فحص داتا قبل destroy ════ */
function _empKpiDrawCharts(rows) {
  const n_  = v => { const x = parseFloat(String(v||'').replace(/%/g,'').replace(/,/g,'')); return isNaN(x)?0:x; };
  const str = v => String(v||'').trim();

  /* ── 1. توزيع التقديرات — Doughnut ── */
  const gradeCtx = document.getElementById('emp-ch-grades');
  if (gradeCtx) {
    _empSafeDestroyChart('grades');
    const counts = EMP_GRADE_ORDER.map(g => rows.filter(r=>str(r['التقدير'])===g).length);
    if (counts.some(c => c > 0)) {
      EMP_KPI.charts.grades = new Chart(gradeCtx, {
        type: 'doughnut',
        data: {
          labels: EMP_GRADE_ORDER,
          datasets: [{ data: counts, backgroundColor: EMP_GRADE_ORDER.map(g=>EMP_GRADE_COLORS[g]?.color||'#94A3B8'), borderWidth: 2, borderColor: '#fff' }]
        },
        options: {
          responsive: true, maintainAspectRatio: false, cutout: '62%',
          plugins: {
            legend: { position: 'bottom', labels: { font:{family:'Tajawal',size:11}, padding:14 } },
            tooltip: { callbacks: { label: c => ` ${c.raw} موظف (${rows.length?((c.raw/rows.length)*100).toFixed(1):0}%)` } }
          }
        }
      });
    } else {
      gradeCtx.parentElement.innerHTML = '<div style="text-align:center;padding:40px;color:var(--tx-muted);font-size:12px">لا توجد بيانات تقديرات</div>';
    }
  }

  /* ── 2. متوسط الدرجة حسب المنطقة — Bar ── */
  const regCtx = document.getElementById('emp-ch-regions');
  if (regCtx) {
    _empSafeDestroyChart('regions');
    const regionMap = {};
    rows.forEach(r => {
      const reg = str(r['المنطقة']);
      if (!reg) return;
      if (!regionMap[reg]) regionMap[reg] = [];
      regionMap[reg].push(n_(r['الدرجة']));
    });
    const regLabels = Object.keys(regionMap).sort();
    const regAvgs   = regLabels.map(reg => +(regionMap[reg].reduce((s,x)=>s+x,0)/regionMap[reg].length).toFixed(1));
    const regCounts = regLabels.map(reg => regionMap[reg].length);

    if (regLabels.length > 0) {
      EMP_KPI.charts.regions = new Chart(regCtx, {
        type: 'bar',
        data: {
          labels: regLabels,
          datasets: [{
            label: 'متوسط الدرجة',
            data: regAvgs,
            backgroundColor: regAvgs.map(v=>v>=85?'#15803D99':v>=70?'#10B98199':v>=55?'#3B82F699':v>=40?'#F59E0B99':'#EF444499'),
            borderRadius: 6
          }]
        },
        options: {
          responsive: true, maintainAspectRatio: false,
          plugins: {
            legend: { display: false },
            tooltip: { callbacks: { label: (c) => {
              const reg = c.label;
              const cnt = regCounts[c.dataIndex];
              return [` الدرجة: ${c.raw} / 100`, ` عدد الموظفين: ${cnt}`];
            }}}
          },
          scales: {
            y: { min:0, max:100, ticks:{font:{family:'Tajawal',size:10}}, grid:{color:'rgba(0,0,0,.04)'} },
            x: { ticks:{font:{family:'Tajawal',size:11}} }
          }
        }
      });
    } else {
      regCtx.parentElement.innerHTML = '<div style="text-align:center;padding:40px;color:var(--tx-muted);font-size:12px">لا توجد بيانات مناطق</div>';
    }
  }

  /* ── 3. مقارنة المؤشرات الخمسة — Bar أفقي ── */
  const metCtx = document.getElementById('emp-ch-metrics');
  if (metCtx) {
    _empSafeDestroyChart('metrics');
    const METRIC_KEYS   = ['الإنجاز %','توثيق بالصور %','التعليقات %','جودة التقرير %','وقت الزيارة %'];
    const METRIC_LABELS = ['الإنجاز','توثيق بالصور','التعليقات','جودة التقرير','وقت الزيارة'];
    const metAvgs = METRIC_KEYS.map(k => +(rows.reduce((s,r)=>s+n_(r[k]),0)/rows.length).toFixed(1));

    if (metAvgs.some(v => v > 0)) {
      EMP_KPI.charts.metrics = new Chart(metCtx, {
        type: 'bar',
        data: {
          labels: METRIC_LABELS,
          datasets: [{
            label: 'متوسط %',
            data: metAvgs,
            backgroundColor: metAvgs.map(v=>v>=85?'#15803D99':v>=70?'#10B98199':v>=55?'#3B82F699':v>=40?'#F59E0B99':'#EF444499'),
            borderRadius: 6,
            indexAxis: 'y'
          }]
        },
        options: {
          responsive: true, maintainAspectRatio: false, indexAxis: 'y',
          plugins: {
            legend: { display: false },
            tooltip: { callbacks: { label: c => ` ${c.raw}%` } }
          },
          scales: {
            x: { min:0, max:100, ticks:{font:{family:'Tajawal',size:10}}, grid:{color:'rgba(0,0,0,.04)'} },
            y: { ticks:{font:{family:'Tajawal',size:11},autoSkip:false} }
          }
        }
      });
    } else {
      metCtx.parentElement.innerHTML = '<div style="text-align:center;padding:40px;color:var(--tx-muted);font-size:12px">لا توجد بيانات مؤشرات</div>';
    }
  }
}

/* ════ مسح الفلاتر ════ */
function _empKpiClearFilters() {
  ['emp-filter-region','emp-filter-role','emp-filter-grade'].forEach(id=>{const e=document.getElementById(id);if(e)e.value='';});
  const s=document.getElementById('emp-search'); if(s) s.value='';
  const so=document.getElementById('emp-sort');  if(so) so.value='score_desc';
  EMP_KPI._region=''; EMP_KPI._role=''; EMP_KPI._grade=''; EMP_KPI._search=''; EMP_KPI._sort='score_desc';
  EMP_KPI.page=0;
  _empKpiRender();
}

/* ════ تصدير CSV ════ */
function _empKpiExportCSV() {
  const src = EMP_KPI.filtered.length ? EMP_KPI.filtered : (window.RAW_EMP_KPI||[]);
  if (!src.length) { alert('لا توجد بيانات'); return; }
  const headers = Object.keys(src[0]);
  const rows    = src.map(r => headers.map(h=>`"${String(r[h]??'').replace(/"/g,'""')}"`).join(','));
  const a = Object.assign(document.createElement('a'), {
    href: URL.createObjectURL(new Blob(['\uFEFF'+[headers.join(','),...rows].join('\n')],{type:'text/csv;charset=utf-8;'})),
    download: 'تقييم_الموظفين.csv'
  });
  a.click();
}

/* ════════════════════════════════════════════════════════════════════
   🦺  تبويب مؤشرات أداء فريق السلامة — tab-safety-kpi                ║
   ════════════════════════════════════════════════════════════════════
   المصدر : window.RAW_SAFETY_KPI  ← شيت "مؤشرات_أداء_فريق_السلامة" في Google Sheet
   المفتاح: d.safetyTeamKpi  (يُعيَّن في loadData عبر sa(d.safetyTeamKpi))

   بيانات أسبوعية لكل منطقة (صف واحد = أسبوع + منطقة).

   ┌─ شرح الأعمدة ──────────────────────────────────────────────────┐
   │  الأسبوع                                    : تاريخ بداية الأسبوع │
   │  المنطقة                                    : المنطقة الجغرافية  │
   │  عدد المشرفين للسلامة                       : مشرفو السلامة       │
   │  عدد الزيارات الميدانية المقررة              : زيارات مخططة       │
   │  عدد الزيارات المنفذة                        : زيارات تم تنفيذها  │
   │  عدد الحوادث المبلغ عنها                     : حوادث مُبلغة        │
   │  عدد الحوادث التي تم اصدار التقرير المبدئي لها: تقارير مبدئية     │
   │  إصابات شخصية                                : عدد المصابين       │
   │  عدد الحوادث التي تم التحقيق فيها             : حوادث محقَّقة      │
   │  عدد الإجراءات التصحيحية المرسلة للمقاول      : إجراءات تصحيحية   │
   │  عدد أوامر العمل من الزيارات التي تم ارسالها للمقاول: أوامر عمل   │
   │  التدريب الأسبوعي - مقرر                     : تدريب مخطط         │
   │  التدريب الأسبوعي - منفذ                     : تدريب منفَّذ        │
   │  تعميمات/ دروس منشورة                        : تعميمات ودروس مستفادة│
   │  العدد الكلي لموظفي المنطقة                  : إجمالي موظفي المنطقة│
   └────────────────────────────────────────────────────────────────┘

   ⚠️  AI MAINTAINER NOTE — اقرأ هذا قبل أي تعديل:
   ══════════════════════════════════════════════════════════════════
   إذا أضفت أعمدة جديدة لشيت مؤشرات_أداء_فريق_السلامة، أو غيّرت أسماء
   الأعمدة، يجب عليك تحديث:
     1. دالة renderSafetyKpiTab()   ← أعمدة الجدول + الـ KPIs
     2. دالة _safetyKpiDrawCharts() ← الرسوم البيانية
     3. دالة _safetyKpiRender()     ← منطق الفلترة والترتيب
     4. قسم summary.مؤشرات_أداء_فريق_السلامة في دالة _fcbBuildSummary()
        (قرب نهاية قسم الشاتبوت) لأن الشاتبوت يقرأ منه.
   ══════════════════════════════════════════════════════════════════ */

const SAFETY_KPI = {
  page: 0,
  pageSize: 20,
  filtered: [],
  charts: {},
  _region: '',
  _week: '',
  _search: '',
  _sort: 'week_desc',
};
window.SAFETY_KPI = SAFETY_KPI;

/* ── مساعد destroy آمن ── */
function _safetySafeDestroyChart(key) {
  const ch = SAFETY_KPI.charts[key];
  if (!ch) return;
  try { ch.destroy(); } catch (_) {}
  delete SAFETY_KPI.charts[key];
}

/* ── ترتيب الأسابيع زمنيًا (النص الأصلي تاريخ قابل للتحويل) ── */
function _safetyWeekSortVal(w) {
  const t = Date.parse(w);
  return isNaN(t) ? 0 : t;
}

/* ════ الدالة الرئيسية ════ */
function renderSafetyKpiTab() {
  const el = document.getElementById('safety-kpi-content');
  if (!el) return;

  const rows = window.RAW_SAFETY_KPI || [];
  if (!rows.length) {
    el.innerHTML = `
      <div class="card" style="text-align:center;padding:60px 24px">
        <div style="font-size:48px;margin-bottom:12px">🦺</div>
        <div style="font-size:16px;font-weight:700;color:var(--tx-main)">لا توجد بيانات مؤشرات أداء فريق السلامة</div>
        <div style="font-size:12px;color:var(--tx-muted);margin-top:8px">
          تأكد من وجود شيت "مؤشرات_أداء_فريق_السلامة" في ملف البيانات وأن الـ Apps Script يقرأها
        </div>
      </div>`;
    return;
  }

  const n_  = v => { const x = parseFloat(String(v||'').replace(/%/g,'').replace(/,/g,'')); return isNaN(x) ? 0 : x; };
  const str = v => String(v||'').trim();
  const pct1 = (a,b) => b ? ((a/b)*100).toFixed(1)+'%' : '—';

  /* ── إحصاءات عامة ── */
  const total       = rows.length;
  const regions     = [...new Set(rows.map(r=>str(r['المنطقة'])).filter(Boolean))].sort();
  const weeks       = [...new Set(rows.map(r=>str(r['الأسبوع'])).filter(Boolean))]
                         .sort((a,b)=>_safetyWeekSortVal(a)-_safetyWeekSortVal(b));

  const sum = key => rows.reduce((s,r)=>s+n_(r[key]),0);
  const visitsPlanned  = sum('عدد الزيارات الميدانية المقررة');
  const visitsDone     = sum('عدد الزيارات المنفذة');
  const incidents      = sum('عدد الحوادث المبلغ عنها');
  const injuries       = sum('إصابات شخصية');
  const investigated   = sum('عدد الحوادث التي تم التحقيق فيها');
  const correctiveActs = sum('عدد الإجراءات التصحيحية المرسلة للمقاول');
  const trainPlanned   = sum('التدريب الأسبوعي - مقرر');
  const trainDone      = sum('التدريب الأسبوعي - منفذ');

  /* ── بناء الصفحة ── */
  el.innerHTML = `

  <!-- ══ شريط العنوان ══ -->
  <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px;margin-bottom:14px">
    <div style="display:flex;align-items:center;gap:12px">
      <span style="font-size:26px">🦺</span>
      <div>
        <div style="font-size:15px;font-weight:800;color:var(--tx-main)">لوحة مؤشرات أداء فريق السلامة</div>
        <div style="font-size:11px;color:var(--tx-muted)">
          ${total.toLocaleString('ar')} سجل أسبوعي · ${regions.length} منطقة · ${weeks.length} أسبوع
        </div>
      </div>
    </div>
    <div style="display:flex;gap:8px;align-items:center">
      <button class="export-btn export-btn-csv" onclick="_safetyKpiExportCSV()" style="font-size:11px">⬇ تصدير CSV</button>
    </div>
  </div>

  <!-- ══ فلاتر موحدة ══ -->
  <div style="display:flex;align-items:flex-end;gap:10px;flex-wrap:wrap;padding:14px 16px;
       margin-bottom:14px;border-radius:14px;background:var(--bg-2,#f8fafc);border:1.5px solid var(--bd-light,#e2e8f0)">
    <div class="fg" style="margin:0;min-width:130px">
      <div class="fg-lbl">المنطقة</div>
      <select class="fsel" id="safety-filter-region"
        onchange="SAFETY_KPI._region=this.value;SAFETY_KPI.page=0;_safetyKpiRender()">
        <option value="">— الكل —</option>
        ${regions.map(r=>`<option value="${r}">${r}</option>`).join('')}
      </select>
    </div>
    <div class="fg" style="margin:0;min-width:160px">
      <div class="fg-lbl">الأسبوع</div>
      <select class="fsel" id="safety-filter-week"
        onchange="SAFETY_KPI._week=this.value;SAFETY_KPI.page=0;_safetyKpiRender()">
        <option value="">— الكل —</option>
        ${weeks.map(w=>`<option value="${w}">${w}</option>`).join('')}
      </select>
    </div>
    <div class="fg" style="margin:0;flex:1;min-width:180px">
      <div class="fg-lbl">بحث بالمنطقة</div>
      <input class="finp" id="safety-search" placeholder="اسم المنطقة..."
        oninput="SAFETY_KPI._search=this.value;SAFETY_KPI.page=0;_safetyKpiRender()">
    </div>
    <div class="fg" style="margin:0">
      <div class="fg-lbl">ترتيب</div>
      <select class="fsel" id="safety-sort"
        onchange="SAFETY_KPI._sort=this.value;SAFETY_KPI.page=0;_safetyKpiRender()">
        <option value="week_desc">الأسبوع (الأحدث أولاً)</option>
        <option value="week_asc">الأسبوع (الأقدم أولاً)</option>
        <option value="incidents_desc">الحوادث ↓</option>
        <option value="visits_desc">الزيارات المنفذة ↓</option>
      </select>
    </div>
    <button class="f-clear" onclick="_safetyKpiClearFilters()" style="margin:0;align-self:flex-end">✕ مسح</button>
  </div>

  <!-- ══ KPIs ══ -->
  <div class="kpi-grid" style="margin-bottom:14px;grid-template-columns:repeat(4,minmax(0,1fr))">
    <div class="kpi kc-blue">
      <div class="kpi-val" id="safety-k-visits">${pct1(visitsDone, visitsPlanned)}</div>
      <div class="kpi-lbl">نسبة تنفيذ الزيارات الميدانية</div>
      <div class="kpi-sub" id="safety-k-visits-sub">${visitsDone.toLocaleString('ar')} من ${visitsPlanned.toLocaleString('ar')}</div>
    </div>
    <div class="kpi kc-teal">
      <div class="kpi-val" id="safety-k-training">${pct1(trainDone, trainPlanned)}</div>
      <div class="kpi-lbl">نسبة تنفيذ التدريب الأسبوعي</div>
      <div class="kpi-sub" id="safety-k-training-sub">${trainDone.toLocaleString('ar')} من ${trainPlanned.toLocaleString('ar')}</div>
    </div>
    <div class="kpi kc-red">
      <div class="kpi-val" id="safety-k-incidents">${incidents.toLocaleString('ar')}</div>
      <div class="kpi-lbl">إجمالي الحوادث المبلغ عنها</div>
      <div class="kpi-sub" id="safety-k-investigated-sub">${investigated.toLocaleString('ar')} تم التحقيق فيها</div>
    </div>
    <div class="kpi kc-green">
      <div class="kpi-val" id="safety-k-actions">${correctiveActs.toLocaleString('ar')}</div>
      <div class="kpi-lbl">إجراءات تصحيحية مرسلة للمقاول</div>
      <div class="kpi-sub" id="safety-k-injuries-sub">${injuries.toLocaleString('ar')} إصابة شخصية</div>
    </div>
  </div>

  <!-- ══ الرسوم البيانية ══ -->
  <div class="g2 mb14">
    <div class="card">
      <div class="card-title">
        <span class="card-title-icon" style="background:#EFF6FF;color:#1D4ED8"><svg class="cti-svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect width="7" height="7" x="3" y="3" rx="1"/><rect width="7" height="7" x="14" y="3" rx="1"/><rect width="7" height="7" x="14" y="14" rx="1"/><rect width="7" height="7" x="3" y="14" rx="1"/></svg></span>
        الزيارات الميدانية: مقرر مقابل منفذ حسب المنطقة
        <span class="sub">إجمالي كل الأسابيع</span>
      </div>
      <div class="chart-box" style="height:240px"><canvas id="safety-ch-visits"></canvas></div>
    </div>
    <div class="card">
      <div class="card-title">
        <span class="card-title-icon" style="background:#FEF2F2;color:#DC2626"><svg class="cti-svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><circle cx="12" cy="12" r="1"/></svg></span>
        الحوادث والإصابات حسب الأسبوع
        <span class="sub">اتجاه أسبوعي</span>
      </div>
      <div class="chart-box" style="height:240px"><canvas id="safety-ch-incidents"></canvas></div>
    </div>
  </div>

  <div class="card mb14">
    <div class="card-title">
      <span class="card-title-icon" style="background:#F0FDF4;color:#059669"><svg class="cti-svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 5h.01"/><path d="M3 12h.01"/><path d="M3 19h.01"/><path d="M8 5h13"/><path d="M8 12h13"/><path d="M8 19h13"/></svg></span>
      التدريب الأسبوعي: مقرر مقابل منفذ حسب المنطقة
      <span class="sub">إجمالي كل الأسابيع</span>
    </div>
    <div class="chart-box" style="height:260px"><canvas id="safety-ch-training"></canvas></div>
  </div>

  <!-- ══ جدول التفاصيل ══ -->
  <div class="card mb14">
    <div class="card-title">
      <span class="card-title-icon" style="background:#F0F9FF;color:#0369A1"><svg class="cti-svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3v18"/><rect width="18" height="18" x="3" y="3" rx="2"/><path d="M3 9h18"/><path d="M3 15h18"/></svg></span>
      التفاصيل الأسبوعية حسب المنطقة
      <span class="sub" id="safety-tbl-count"></span>
    </div>

    <div class="tbl-wrap">
      <table>
        <thead>
          <tr>
            <th style="min-width:150px;text-align:right;padding-right:14px">الأسبوع</th>
            <th>المنطقة</th>
            <th title="عدد مشرفي السلامة">المشرفون</th>
            <th title="الزيارات الميدانية المقررة">مقرر</th>
            <th title="الزيارات الميدانية المنفذة" style="color:#059669">منفذ</th>
            <th title="عدد الحوادث المبلغ عنها" style="color:#DC2626">الحوادث</th>
            <th title="عدد التقارير المبدئية">التقرير المبدئي</th>
            <th title="إصابات شخصية" style="color:#DC2626">الإصابات</th>
            <th title="عدد الحوادث المحقَّقة">تم التحقيق</th>
            <th title="الإجراءات التصحيحية المرسلة للمقاول">إجراءات تصحيحية</th>
            <th title="أوامر العمل المرسلة للمقاول">أوامر عمل</th>
            <th title="التدريب الأسبوعي المقرر">تدريب مقرر</th>
            <th title="التدريب الأسبوعي المنفذ" style="color:#059669">تدريب منفذ</th>
            <th title="تعميمات ودروس مستفادة منشورة">تعميمات/دروس</th>
            <th title="إجمالي موظفي المنطقة">إجمالي الموظفين</th>
          </tr>
        </thead>
        <tbody id="safety-tbl-body"></tbody>
      </table>
    </div>
    <div class="pag-bar" id="safety-pag" style="margin-top:8px"></div>
  </div>`;

  _safetyKpiDrawCharts(rows);
  _safetyKpiRender();
}

/* ════ فلترة + تحديث KPIs + جدول ════ */
function _safetyKpiRender() {
  const rows = window.RAW_SAFETY_KPI || [];
  const n_  = v => { const x = parseFloat(String(v||'').replace(/%/g,'').replace(/,/g,'')); return isNaN(x)?0:x; };
  const str = v => String(v||'').trim();
  const q   = (SAFETY_KPI._search||'').trim().toLowerCase();

  let list = rows.filter(r => {
    if (SAFETY_KPI._region && str(r['المنطقة']) !== SAFETY_KPI._region) return false;
    if (SAFETY_KPI._week   && str(r['الأسبوع'])  !== SAFETY_KPI._week)  return false;
    if (q && !str(r['المنطقة']).toLowerCase().includes(q)) return false;
    return true;
  });

  list.sort((a,b) => {
    if (SAFETY_KPI._sort === 'week_desc')      return _safetyWeekSortVal(str(b['الأسبوع'])) - _safetyWeekSortVal(str(a['الأسبوع']));
    if (SAFETY_KPI._sort === 'week_asc')       return _safetyWeekSortVal(str(a['الأسبوع'])) - _safetyWeekSortVal(str(b['الأسبوع']));
    if (SAFETY_KPI._sort === 'incidents_desc') return n_(b['عدد الحوادث المبلغ عنها']) - n_(a['عدد الحوادث المبلغ عنها']);
    if (SAFETY_KPI._sort === 'visits_desc')    return n_(b['عدد الزيارات المنفذة']) - n_(a['عدد الزيارات المنفذة']);
    return 0;
  });

  SAFETY_KPI.filtered = list;
  const t = list.length;

  const sum = key => list.reduce((s,r)=>s+n_(r[key]),0);
  const visitsPlanned  = sum('عدد الزيارات الميدانية المقررة');
  const visitsDone     = sum('عدد الزيارات المنفذة');
  const incidents      = sum('عدد الحوادث المبلغ عنها');
  const injuries       = sum('إصابات شخصية');
  const investigated   = sum('عدد الحوادث التي تم التحقيق فيها');
  const correctiveActs = sum('عدد الإجراءات التصحيحية المرسلة للمقاول');
  const trainPlanned   = sum('التدريب الأسبوعي - مقرر');
  const trainDone      = sum('التدريب الأسبوعي - منفذ');
  const pct1 = (a,b) => b ? ((a/b)*100).toFixed(1)+'%' : '—';

  const ge = id => document.getElementById(id);
  const set = (id,v) => { const e=ge(id); if(e) e.textContent=v; };
  set('safety-k-visits',        pct1(visitsDone, visitsPlanned));
  set('safety-k-visits-sub',    `${visitsDone.toLocaleString('ar')} من ${visitsPlanned.toLocaleString('ar')}`);
  set('safety-k-training',      pct1(trainDone, trainPlanned));
  set('safety-k-training-sub',  `${trainDone.toLocaleString('ar')} من ${trainPlanned.toLocaleString('ar')}`);
  set('safety-k-incidents',     incidents.toLocaleString('ar'));
  set('safety-k-investigated-sub', `${investigated.toLocaleString('ar')} تم التحقيق فيها`);
  set('safety-k-actions',       correctiveActs.toLocaleString('ar'));
  set('safety-k-injuries-sub',  `${injuries.toLocaleString('ar')} إصابة شخصية`);
  set('safety-tbl-count',       t.toLocaleString('ar') + ' سجل');

  _safetyKpiDrawTable();
}

/* ════ جدول مع pagination ════ */
function _safetyKpiDrawTable() {
  const list = SAFETY_KPI.filtered;
  const st   = SAFETY_KPI.page * SAFETY_KPI.pageSize;
  const tb   = document.getElementById('safety-tbl-body');
  if (!tb) return;

  const n_  = v => { const x = parseFloat(String(v||'').replace(/%/g,'').replace(/,/g,'')); return isNaN(x)?0:x; };
  const str = v => String(v||'').trim();

  tb.innerHTML = list.slice(st, st + SAFETY_KPI.pageSize).map(r => {
    const incidents = n_(r['عدد الحوادث المبلغ عنها']);
    const injuries  = n_(r['إصابات شخصية']);
    return `<tr>
      <td style="text-align:right;padding-right:14px;font-weight:700;font-size:12px">${str(r['الأسبوع'])}</td>
      <td>${str(r['المنطقة'])}</td>
      <td style="text-align:center">${n_(r['عدد المشرفين للسلامة'])}</td>
      <td style="text-align:center">${n_(r['عدد الزيارات الميدانية المقررة'])}</td>
      <td style="color:#059669;font-weight:700;text-align:center">${n_(r['عدد الزيارات المنفذة'])}</td>
      <td style="color:${incidents>0?'#DC2626':'var(--tx-muted)'};font-weight:${incidents>0?'700':'400'};text-align:center">${incidents}</td>
      <td style="text-align:center">${n_(r['عدد الحوادث التي تم اصدار التقرير المبدئي لها'])}</td>
      <td style="color:${injuries>0?'#DC2626':'var(--tx-muted)'};font-weight:${injuries>0?'700':'400'};text-align:center">${injuries}</td>
      <td style="text-align:center">${n_(r['عدد الحوادث التي تم التحقيق فيها'])}</td>
      <td style="text-align:center">${n_(r['عدد الإجراءات التصحيحية المرسلة للمقاول'])}</td>
      <td style="text-align:center">${n_(r['عدد أوامر العمل من الزيارات التي تم ارسالها للمقاول'])}</td>
      <td style="text-align:center">${n_(r['التدريب الأسبوعي - مقرر'])}</td>
      <td style="color:#059669;font-weight:700;text-align:center">${n_(r['التدريب الأسبوعي - منفذ'])}</td>
      <td style="text-align:center">${str(r['تعميمات/ دروس منشورة']) || '—'}</td>
      <td style="text-align:center">${n_(r['العدد الكلي لموظفي المنطقة'])}</td>
    </tr>`;
  }).join('');

  /* pagination */
  const pag   = document.getElementById('safety-pag');
  const pages = Math.ceil(list.length / SAFETY_KPI.pageSize);
  if (!pag) return;
  if (pages <= 1) { pag.innerHTML = ''; return; }
  let h = `<span class="pag-info">صفحة ${SAFETY_KPI.page+1} من ${pages}</span><div class="pag-btns">`;
  h += `<button class="pag-btn" ${SAFETY_KPI.page===0?'disabled':''} onclick="SAFETY_KPI.page--;_safetyKpiDrawTable()">→ السابق</button>`;
  let s=Math.max(0,SAFETY_KPI.page-3), e=Math.min(pages-1,s+6);
  if(e-s<6) s=Math.max(0,e-6);
  for(let p=s;p<=e;p++) h+=`<button class="pag-btn${p===SAFETY_KPI.page?' active':''}" onclick="SAFETY_KPI.page=${p};_safetyKpiDrawTable()">${p+1}</button>`;
  h += `<button class="pag-btn" ${SAFETY_KPI.page===pages-1?'disabled':''} onclick="SAFETY_KPI.page++;_safetyKpiDrawTable()">← التالي</button></div>`;
  pag.innerHTML = h;
}

/* ════ الشارتات ════ */
function _safetyKpiDrawCharts(rows) {
  const n_  = v => { const x = parseFloat(String(v||'').replace(/%/g,'').replace(/,/g,'')); return isNaN(x)?0:x; };
  const str = v => String(v||'').trim();

  /* ── 1. الزيارات: مقرر مقابل منفذ حسب المنطقة — Bar مزدوج ── */
  const visCtx = document.getElementById('safety-ch-visits');
  if (visCtx) {
    _safetySafeDestroyChart('visits');
    const regionMap = {};
    rows.forEach(r => {
      const reg = str(r['المنطقة']); if (!reg) return;
      if (!regionMap[reg]) regionMap[reg] = { planned:0, done:0 };
      regionMap[reg].planned += n_(r['عدد الزيارات الميدانية المقررة']);
      regionMap[reg].done    += n_(r['عدد الزيارات المنفذة']);
    });
    const labels = Object.keys(regionMap).sort();
    if (labels.length) {
      SAFETY_KPI.charts.visits = new Chart(visCtx, {
        type: 'bar',
        data: {
          labels,
          datasets: [
            { label: 'مقرر', data: labels.map(r=>regionMap[r].planned), backgroundColor: '#93C5FD99', borderRadius: 6 },
            { label: 'منفذ', data: labels.map(r=>regionMap[r].done),    backgroundColor: '#10B98199', borderRadius: 6 },
          ]
        },
        options: {
          responsive: true, maintainAspectRatio: false,
          plugins: { legend: { position:'bottom', labels:{font:{family:'Tajawal',size:11}} } },
          scales: {
            y: { beginAtZero:true, ticks:{font:{family:'Tajawal',size:10}}, grid:{color:'rgba(0,0,0,.04)'} },
            x: { ticks:{font:{family:'Tajawal',size:11}} }
          }
        }
      });
    } else {
      visCtx.parentElement.innerHTML = '<div style="text-align:center;padding:40px;color:var(--tx-muted);font-size:12px">لا توجد بيانات مناطق</div>';
    }
  }

  /* ── 2. الحوادث والإصابات حسب الأسبوع — Line ── */
  const incCtx = document.getElementById('safety-ch-incidents');
  if (incCtx) {
    _safetySafeDestroyChart('incidents');
    const weekMap = {};
    rows.forEach(r => {
      const wk = str(r['الأسبوع']); if (!wk) return;
      if (!weekMap[wk]) weekMap[wk] = { incidents:0, injuries:0 };
      weekMap[wk].incidents += n_(r['عدد الحوادث المبلغ عنها']);
      weekMap[wk].injuries  += n_(r['إصابات شخصية']);
    });
    const wLabels = Object.keys(weekMap).sort((a,b)=>_safetyWeekSortVal(a)-_safetyWeekSortVal(b));
    if (wLabels.length) {
      SAFETY_KPI.charts.incidents = new Chart(incCtx, {
        type: 'line',
        data: {
          labels: wLabels,
          datasets: [
            { label: 'الحوادث المبلغ عنها', data: wLabels.map(w=>weekMap[w].incidents), borderColor:'#DC2626', backgroundColor:'#DC262622', tension:.3, fill:true },
            { label: 'الإصابات الشخصية',   data: wLabels.map(w=>weekMap[w].injuries),  borderColor:'#D97706', backgroundColor:'#D9770622', tension:.3, fill:true },
          ]
        },
        options: {
          responsive: true, maintainAspectRatio: false,
          plugins: { legend: { position:'bottom', labels:{font:{family:'Tajawal',size:11}} } },
          scales: {
            y: { beginAtZero:true, ticks:{font:{family:'Tajawal',size:10},stepSize:1}, grid:{color:'rgba(0,0,0,.04)'} },
            x: { ticks:{font:{family:'Tajawal',size:10}} }
          }
        }
      });
    } else {
      incCtx.parentElement.innerHTML = '<div style="text-align:center;padding:40px;color:var(--tx-muted);font-size:12px">لا توجد بيانات حوادث</div>';
    }
  }

  /* ── 3. التدريب: مقرر مقابل منفذ حسب المنطقة — Bar مزدوج ── */
  const trCtx = document.getElementById('safety-ch-training');
  if (trCtx) {
    _safetySafeDestroyChart('training');
    const regionMap = {};
    rows.forEach(r => {
      const reg = str(r['المنطقة']); if (!reg) return;
      if (!regionMap[reg]) regionMap[reg] = { planned:0, done:0 };
      regionMap[reg].planned += n_(r['التدريب الأسبوعي - مقرر']);
      regionMap[reg].done    += n_(r['التدريب الأسبوعي - منفذ']);
    });
    const labels = Object.keys(regionMap).sort();
    if (labels.length) {
      SAFETY_KPI.charts.training = new Chart(trCtx, {
        type: 'bar',
        data: {
          labels,
          datasets: [
            { label: 'مقرر', data: labels.map(r=>regionMap[r].planned), backgroundColor: '#FCD34D99', borderRadius: 6 },
            { label: 'منفذ', data: labels.map(r=>regionMap[r].done),    backgroundColor: '#059669AA', borderRadius: 6 },
          ]
        },
        options: {
          responsive: true, maintainAspectRatio: false,
          plugins: { legend: { position:'bottom', labels:{font:{family:'Tajawal',size:11}} } },
          scales: {
            y: { beginAtZero:true, ticks:{font:{family:'Tajawal',size:10}}, grid:{color:'rgba(0,0,0,.04)'} },
            x: { ticks:{font:{family:'Tajawal',size:11}} }
          }
        }
      });
    } else {
      trCtx.parentElement.innerHTML = '<div style="text-align:center;padding:40px;color:var(--tx-muted);font-size:12px">لا توجد بيانات تدريب</div>';
    }
  }
}

/* ════ مسح الفلاتر ════ */
function _safetyKpiClearFilters() {
  ['safety-filter-region','safety-filter-week'].forEach(id=>{const e=document.getElementById(id);if(e)e.value='';});
  const s=document.getElementById('safety-search'); if(s) s.value='';
  const so=document.getElementById('safety-sort');  if(so) so.value='week_desc';
  SAFETY_KPI._region=''; SAFETY_KPI._week=''; SAFETY_KPI._search=''; SAFETY_KPI._sort='week_desc';
  SAFETY_KPI.page=0;
  _safetyKpiRender();
}

/* ════ تصدير CSV ════ */
function _safetyKpiExportCSV() {
  const src = SAFETY_KPI.filtered.length ? SAFETY_KPI.filtered : (window.RAW_SAFETY_KPI||[]);
  if (!src.length) { alert('لا توجد بيانات'); return; }
  const headers = Object.keys(src[0]);
  const rows    = src.map(r => headers.map(h=>`"${String(r[h]??'').replace(/"/g,'""')}"`).join(','));
  const a = Object.assign(document.createElement('a'), {
    href: URL.createObjectURL(new Blob(['\uFEFF'+[headers.join(','),...rows].join('\n')],{type:'text/csv;charset=utf-8;'})),
    download: 'مؤشرات_أداء_فريق_السلامة.csv'
  });
  a.click();
}

